// Тлумачення Псалтиря Євфимія Зигабена (переклад українською з російського видання) — http://mediaglagol.com.ua/book/tolkovaya_psaltir
// Файл згенеровано scripts/build_tlumach.py з scripts/zigaben/uk/, не правте вручну.
import type { TlumPsalms } from './index';
// Кафизма 12: псалми 85–90.
export const Z: TlumPsalms = {"85":[{"v":"0","t":["Молитва Давидова","Зміст надписання ясний; про це надписання ми говорили у вступі. Молячись за самого себе, Давид навчає, як треба молитися, перебуваючи в нужді. Передрікає ж тут і про покликання язичників. Деякі ж кажуть, що ця молитва написана від особи Єзекії."]},{"v":"1","t":["Як Бог прихиляє вуха, сказано в 16-му псалмі.","«Бо я вбогий і бідний»","Бо не маю достатніх сил проти видимих і невидимих ворогів і не можу їм протистояти."],"h":"Прихили, Господи, вухо Твоє й почуй мене"},{"v":"2","t":["Спаси мене, бо я присвячений, або принесений Тобі, як сказано й у 15-му псалмі. Або ж називає преподобним самого себе, як благочестивого порівняно з нечестивими його ворогами.","«Спаси раба Твого, Боже мій, що надіється на Тебе»","Спаси від небезпеки, що загрожує, того, хто надіється тільки на Тебе одного."],"h":"Збережи душу мою, бо я преподобний"},{"v":"3","t":["Симмах переклав «завжди» замість «весь день»."],"h":"Помилуй мене, Господи, бо до Тебе взиватиму весь день"},{"v":"4","t":["Визволи від скорботи, що мене охопила. Про слова «підніс душу мою» сказано в першому вірші 24-го псалма."],"h":"Звесели душу раба Твого, бо до Тебе я підніс душу мою"},{"v":"5","t":["Замість «лагідний» Акила й Симмах переклали «милостивий». «Хто прикликає Тебе» — не просто, а хто прикликає від усього серця. Бо й у 144-му псалмі, сказавши «близький Господь до всіх, хто прикликає Його», додав: «до всіх, хто прикликає Його в істині», тобто всією душею."],"h":"Бо Ти, Господи, благий, і лагідний, і багатомилостивий до всіх, хто прикликає Тебе"},{"v":"6","t":["Ці слова пояснено на початку 16-го псалма."],"h":"Вислухай, Господи, молитву мою, і почуй голос благання мого"},{"v":"7","t":["Днем скорботи назвав день, що настав. Про слова ж «бо Ти почув мене» сказано в тому самому 16-му псалмі."],"h":"У день скорботи моєї я взивав до Тебе, бо Ти почув мене"},{"v":"8","t":["Бо всі, каже, боги язичників — біси, а Господь небеса створив (Пс. 95:5). Ти — істинний Бог, а вони неправдиві. Цей вірш, здається, запозичений зі слів Мойсея: хто подібний до Тебе серед богів, Господи, хто подібний до Тебе, прославлений у святих, дивний у славі, що твориш чудеса? (Вих. 15:11). А діла Христа — не тільки творіння й промисел про видиме й невидиме створіння, а й переображення самого створіння, і зруйнування тирана, і умертвіння смерті смертю, і впіймання всього світу небагатьма бідними рибалками; до цього можеш додати ще силу чудес. Бо якщо інші й чинили такі чудеса, але ніхто не міг власною силою робити те, що робив Христос, а вони звершували їх прикликанням божественного імені."],"h":"Немає подібного до Тебе серед богів, Господи, і немає діл, як Твої"},{"v":"9-10","t":["Тут пророкує про віру язичників. Прийдуть до Тебе, каже, вірою самі язичники. «Поклоняється» ж «перед Богом» той, хто усвідомлює, що Бог бачить його. «Перед Богом» же — кожне місце Його владицтва. «Прославлять», тобто хвалитимуть і звеличуватимуть Тебе всі язичники, кажучи, що Ти воістину великий і що Ти — єдиний Бог, що твориш чудеса."],"h":"Усі народи, яких Ти створив, прийдуть і поклоняться перед Тобою, Господи, і прославлять ім’я Твоє, бо Ти великий і твориш чудеса, Ти — Бог єдиний"},{"v":"11","t":["Дорогою Господньою називає практичну чесноту, а істиною — споглядальну. Хто приведений Богом до першої з них, легко може перейти й до другої. Про цю дорогу й істину знайдеш і в 24-му псалмі, у словах «дороги Твої, Господи, покажи мені», і в іншому місці: настав мене на істину Твою.","«Нехай звеселиться серце моє боятися імені Твого»","Звеселиться не мирською радістю, а тремтячи перед Твоїм іменем. Дивись, яка дивна радість. Страх перед Тобою, каже, нехай буде мені радістю. А в іншому місці каже: нехай радіє серце тих, що шукають Господа. Шукає ж Бога той, хто боїться Його. Утім, не тільки страх Божий, а й проста пам’ять про Нього радує благочестивих і вірних: я згадав Бога, каже Давид, і звеселився (Пс. 76:4)."],"h":"Настав мене, Господи, на дорогу Твою, і піду в істині Твоїй"},{"v":"12","t":["Тобто дякуватиму.","«І прославлю ім’я Твоє повіки»","Тобто завжди."],"h":"Сповідуватимуся Тобі, Господи, Боже мій, усім серцем моїм"},{"v":"13","t":["«Велика» замість «рясна».","«І Ти визволив душу мою з найглибшого аду»","Щодо Давида під «найглибшим адом» розумій гріх — перелюб і вбивство Урії. Щодо ж Єзекії розумій близьку смерть, що йому загрожувала і від якої він чудесно визволився. Можна також під адом розуміти й усяку небезпеку, що загрожує від видимих чи невидимих ворогів."],"h":"Бо велика милість Твоя до мене"},{"v":"14","t":["Беззаконниками були й вороги Давида, що будували проти нього підступи, і ассирійці, що облягали царя Єзекію; і, нарешті, беззаконниками можуть бути названі й усі наші вороги — як видимі, так і невидимі.","«І зграя сильних шукала душі моєї, і не поставили Тебе перед собою»","Ті самі, кого назвав беззаконниками. Ці слова є й у 53-му псалмі."],"h":"Боже, беззаконники повстали на мене"},{"v":"15","t":["Будучи милосердним і милостивим, Ти завжди співчуваєш пригнобленим; будучи довготерпеливим, не відразу віддаєш грішників у руки ворогів; будучи багатомилостивим, не раз, а часто виявляєш милість; будучи ж правдивим, спасаєш усіх, хто надіється на Тебе."],"h":"А Ти, Господи, Боже мій, щедрий і милостивий, довготерпеливий, і багатомилостивий, і правдивий"},{"v":"16","t":["Цей вірш є й у 24-му псалмі.","«Дай силу Твою отрокові Твоєму»","Силу, або міць, яку можна отримати від Тебе проти ворогів. «Отрокові Твоєму» ж означає «рабові Твоєму».","«І спаси сина рабині Твоєї»","Цими словами пророк показує, що він народився від благочестивих батьків."],"h":"Зглянься на мене й помилуй мене"},{"v":"17","t":["Поклади, каже, Господи, на мене якийсь знак і відзнаку на добро й на спасіння, як Ти поклав на знак на єврейських домах кров агнця, коли винищувалися первістки єгипетські, за словами Афанасія й Феодорита. Сказав «знак на добро», бо є знак і на зло, яким був той, що був покладений на Каїна, як каже Євсевій. Знак, покладений на єврейських домах, був знаком на добро й на спасіння, через який не входив до них губитель, щоб умертвити їхніх первістків; а знак, покладений Богом на Каїна, був знаком на зло, бо означав гнів Божий проти нього.","Прим.: Слова Феодорита: у власному значенні на добре знамення для язичників дарував Бог від Бога хрест, яким переміг спільного ворога й поставив цей переможний знак проти демонів і пристрастей.","«І нехай побачать ті, що ненавидять мене, і посоромляться, бо Ти, Господи, допоміг мені й утішив мене»","Тут вид перестановки, яка виправляється так: і нехай побачать ті, що ненавидять мене, що Ти, Господи, допоміг мені й утішив мене, і посоромляться; тобто нехай бачать, каже, Господи, демони, що ненавидять мене, даний мені Тобою знак на мою допомогу й утіху, і так нехай осоромляться й посоромляться, як переможені, бо побачили, що мене береже Твоя благодать і промисел, за словами Феодорита."],"h":"Учини зі мною знамення на добро"}],"86":[{"v":"0","t":["Пісня псалма. Синам Кореєвим","Про ці два надписання ми сказали в 6-му й 9-му розділах передмови до цієї книги; там і дивись. Цей псалом пророкує про народження Христа й спасіння язичницьких народів, як кажуть Феодорит і Афанасій."]},{"v":"2","t":["Чиї це «Його»? За словами Євсевія, Христові; і це явно з подальших слів, у яких говориться: мати — Сіон, скаже людина, і людина народилася в ньому, і Сам Всевишній заснував його. Основи Христові — це істини вчення про Нього; бо вони є основами й коренем віри в Христа. Ці-то основи покладені, за словами Феодорита й Кирила, на апостолах, яких назвав тут святими горами: горами — бо апостоли були тверді у вірі, підносилися над усяким земним і низьким мудруванням і схильністю й були осінені численними чеснотами, подібно до того, як і гори тверді, високі й осінені густими деревами; а святими — бо апостоли були свято віддані святому Богові й сповнені Духа Святого. Можемо сказати й інакше, що основами Христовими назвав апостолів: основами — бо з апостолів склалися початки й перші будови Церкви Христової, а Христовими — бо апостолів Христос поклав в основу Церкви; бо вони були на горах святих, тобто на Сіоні, Фаворі та інших висотах, особливо освячених перебуванням і життям на них Найсвятішого зі святих — Христа. А деякі кажуть, що основи Христові — пророчі передречення про Христа, бо вони були першими початками віри в Христа; адже святі гори — це й пророки, через висоту пророцтва й освячення їх від Святого Духа. Отже, ця думка показує, що початки віри в Христа були в пророках.","Прим.: Інший каже: зауваж, що «основи його» сказано невизначено, за загальним звичаєм, як і щодо приватних домів часто найкращих із мешканців зазвичай називають основами дому. «Основи його» — не Христа, а народу, покликаного через віру. Слова Ниського: хто такий будівничий храму, що кладе його основи на горах святих, тобто на пророках і апостолах, і на основі апостолів і пророків утверджує живі й одухотворені камені, які, за пророцтвом Ісаї, самі котяться, щоб утворити стрункість стін, щоб, з’єднавшись через єдність віри й союз миру, вирости в святий храм, щоб бути оселею Божою в Дусі? Феодорит: основи благочестя — це божественні настанови; а святі гори, на яких поставлені ці основи, — це апостоли нашого Спасителя. Про них-то сказав блаженний Павло: будучи утверджені на основі апостолів і пророків, маючи наріжним каменем Самого Ісуса Христа; також: Петро, Яків та Іван, яких шанують як стовпів; і ще: ви — світло світу; не може сховатися місто, що стоїть на верху гори. На цих святих горах Владика Христос утвердив основи благочестя.","«Любить Господь брами Сіону понад усі оселі Якова»","Великий Павло в посланні до євреїв (Євр. 12:22) дав нам поняття про існування й небесного Сіону, і небесного Єрусалима, назвавши так небесне життя. Отже, за словами Феодорита, під брамами цього небесного Сіону ти маєш розуміти помісні церкви, як ми сказали й наприкінці 72-го псалма при поясненні слів «у брамах дочки Сіонської»; бо через них, як через двері, входять християни до горнього Сіону. Ці-то брами, тобто помісні церкви, Господь любить і ставить вище за всі міста ізраїльського народу; бо оселі — це міста. Або оселями зокрема називає Шіло й чуттєвий Єрусалим через те, що спершу ковчег мав місце в Шіло, а потім в Єрусалимі, як ми говорили в 77-му псалмі при поясненні слів «оселю, у якій Він перебував серед людей».","Прим.: За словами Афанасія, брамами Сіону називає підготовче початкове вчення Церкви, а оселями Якова — богослужіння за законом і юдейську синагогу; тому він каже: у Бога бажаніше євангельське життя, ніж богослужіння за законом."],"h":"Основи Його на горах святих"},{"v":"3","t":["Почувши голос у серці від Святого Духа й довідавшись, що Бог з’явиться в Єрусалимі й житиме серед людей, Давид був уражений подивом і звернувся до Єрусалима: великі й дивовижні речі сказано мені про тебе, місто Боже, від Духа. Це місто Боже — і тому, що в давнину воно було присвячене Богові, і тому, що згодом воно було призначене Христові для Його страждань у ньому, і гробу, і воскресіння.","Прим.: За словами Афанасія, місто Боже — це Церква, що є наслідуванням і зображенням небесної, а входи до неї (небесної) і початки є тут, у нас, які в цьому місці Писання названі брамами. А те, що про неї звіщене Богом, — щось дивне, преславне й таке, що перевершує всяке людське очікування. Що ж звіщене про неї, як не те, що в ній мав жити Єдинородний, згідно з цими словами: тут Я оселюся, бо Я вибрав його. А за словами божественного Івана Дамаскина, під містом Божим слід розуміти гідну всякого прославлення Богородицю, про Яку преславне сказано те, що в Ній поєднано дівство з народженням через з’єднання Бога з людською природою: Сущий від Неї походить, Творець твориться, і Її дівочі брами, як чисті, творче Слово полюбило, і, увійшовши в ці брами й вийшовши (з них), залишило їх зачиненими."],"h":"Преславне говориться про тебе, місто Боже"},{"v":"4","t":["Ці слова, за поясненням божественного Кирила, сказано від особи Христа Спасителя, і вони містять пророцтво про те, що Його Церква має скластися з багатьох народів, до того ж із найнечестивіших: бо в особі блудниці Рахав зобразив ханаанеїв, бо й Рахав була ханаанкою й жила в землі ханаанській; містом Вавилоном назвав вавилонян; ці ханаанеї й вавилоняни були нечестивіші за всіх інших. Далі він перелічує й інші подібні за нечестям народи; тими, хто знає, називає вірних; і думка тут буде така: серед тих, хто знає Мене, тобто в зібранні вірних у Мене, Я згадуватиму Рахав і Вавилон, інакше кажучи, піклуватимуся про них, як про тих, що увірували в Мене. Деякі під Рахав розуміють Єгипет.","«І ось чужоплемінники, і Тир, і народ ефіопський — вони народилися там»","Там, каже, тобто на Сіоні, або в брамах Сіону, або серед тих, хто знає Бога, інакше кажучи, там, у Церкві Христовій, народилися духовно через святе хрещення тиряни, ефіопи та інші чужоплемінні народи. Акила й Симмах замість «народилися» переклали «збентежилися». Слово «ось» ужито зайво за властивістю єврейської мови; так само й займенник «вони», здається, зайвий, або є повторенням сказаного вище, і може бути побудоване так: «ось» замість «отже», і вони народилися там; хто ж вони? Чужоплемінники, тиряни тощо; а чужоплемінники — це так звані филистимляни, яких звали й ашдодцями, й ашкелонцями, а переважно чужоплемінниками, бо із семи народів, знищених ізраїльтянами, тільки вони залишилися, як ми сказали вище в 82-му псалмі при поясненні слів «чужоплемінники з мешканцями Тиру». Усі згадані народи були дуже нечестиві й беззаконніші за інших. Але якщо ті народи, що були набагато гіршими, мали увірувати в Христа, то чи не тим більше інші, що не так глибоко впали в нечестя?","Прим.: Слова Феодорита: іменем найбеззаконніших народів виразив і інших. Бо Рахав була ханаанкою й блудницею, Вавилон — звіроподібним і нечестивим, а чужоплемінники, тобто филистимляни, — забобонними й беззаконними. Щодо Тиру, то Єзекіїль оплакує його нечестя й розпусту. Народом ефіопським у цих пророчих словах названі не тільки самі ефіопи, чиї душі мали подібність до кольору їхніх тіл, а й усі чорні душею, що перейшли до благочестя й відкинули чорноту нечестя; це в тому й іншому сенсі зображає в пісні наречена, що каже: чорна я, але гарна, дочки єрусалимські! Бо водночас виразила і темряву нечестя, і красу, яку дає божественна благодать. Знайдено також у Феодорита (у примітках) і таке: Рахав у перекладі означає «широчінь», а Вавилон — «змішання»; бо ті, що провадили широке життя й були обтяжені змішанням від демонів, пізнали Бога; і ті, що впали через падіння ідолів (бо чужоплемінники означає «ті, що падають»), і через змішання від омани (бо Тир означає змішання, можливо, оману), і були принижені демонами (бо Ефіопія означає приниження), як ті, що віддалилися від Бога, — народилися там. Як? Через віру й спасіння в час пришестя Христового."],"h":"Згадаю Рахав і Вавилон серед тих, хто знає Мене"},{"v":"5","t":["Тут ясно пророкує божественний Давид, що з кожного народу багато хто піде до Сіону й скаже, що Сіон, тобто Церква, — мати. Тут бракує дієслова «є». За словами Афанасія, мати — це Церква, з одного боку, тому, що духовно народжує вірних святим хрещенням, як ми сказали вище; з другого — оскільки вона годує народжених християн ученням віри про Христа й причастям божественних Таїн, тіла й крові Христової. Або Церква зветься матір’ю тому, що вона бажана й люба для своїх дітей; бо немає нічого бажанішого за матір; і воістину бажаний як чуттєвий, так і мисленний Сіон, тобто Церква, для тих, хто до них прибігає; бо в чуттєвому Сіоні й Єрусалимі жив у тілі Владика Христос і освятив його місця Своїм перебуванням у ньому; а в мисленному Сіоні, тобто Церкві, невидимо живе й ходить Христос, і в ньому звершуються божественні таїнства Христові.","«І людина народилася в ньому»","У цих словах міститься пророцтво про народження Христа, а саме що в межах (країнах) чуттєвого Сіону воістину народився Чоловік Христос, Який зберіг гідність людської природи. А щоб показати, що Народжений не був простою людиною, а людиною й Богом, тому далі каже:","«І Він заснував його — Всевишній»","Він, каже, Той, Хто народився на Сіоні в образі людини, — Він і заснував його на початку, як Творець неба й землі, Який понад усе, як Бог.","Прим.: Феодорит думає, що тут слід мати на увазі спільне дієслово «скаже»; бо той, хто називає Сіон матір’ю, сповідує й народження Людини, що народилася в ньому."],"h":"Мати — Сіон, скаже людина"},{"v":"6","t":["Христос, каже, навчатиме про Себе з Писання, маються на увазі пророчі книги, бо євангеліст Лука розповідає: і подали Йому книгу пророка Ісаї, і Він, розгорнувши книгу, знайшов місце, де було написано: Дух Господній на Мені, бо Він помазав Мене благовістити вбогим, послав Мене тощо (Лк. 4:17–18). Таке писання пророчих слів Давид назвав писанням народів і їхніх начальників, бо Писання дане юдейським племенам та їхнім начальникам. Спочатку Писання становило власність цих племен, народжених тілесно на чуттєвому Сіоні, а тепер те саме Писання стало надбанням тих, хто народився духовно в мисленному Сіоні, у Церкві Христовій, тобто християнській.","Прим.: Слова Феодорита: бо Той, Хто імена народів, що живуть у ньому, удостоює Свого писання, народився в ньому за людською природою, і Він є Господь і Бог. Цього обчислення Господь наш навчив, сказавши святим апостолам: а у вас і волосся на голові все пораховане; а записання відкрив Своїм учням, коли казав: радійте, що імена ваші записані на небесах. Майже те саме каже й Феодор."],"h":"Господь розповість у писанні народів і князів цих, що народилися в ньому"},{"v":"7","t":["Слово «бо» тут ствердне, і зв’язок такий: Сіоне, воістину в тобі оселя всіх, хто веселиться духовно, бо в тобі житимуть такі. Слово «всіх» нібито виражає всіх загалом, але й тут виявляється особливість Писання: воно вживає «всіх» замість «багатьох» або «декількох із багатьох».","Прим.: Інший каже, що ті, чиї імена записуються в небесному Сіоні, матимуть чисту й неудавану веселість і поселяться в ньому не на час, а житимуть у ньому й радітимуть повіки. О, якби й наші імена Господь записав у книгу тих, хто спасається, і сподобив нас тієї насолоди, де оселя всіх, хто веселиться! Слова Феодорита: небесне життя далеке від усякої печалі й має чисту та безсмертну веселість і втіху; у ньому вихованці благочестя житимуть не тимчасово, а вічно. Слова Афанасія: коли, каже, буде в тобі оселя всіх, хто належить до Церкви, тоді вони сповняться веселощів."],"h":"Бо в тобі оселя всіх, хто веселиться"}],"87":[{"v":"0","t":["Пісня псалма. Синам Кореєвим. На кінець. Про Маелеф, щоб відповідати. Повчання Емана, ізраїльтянина","Що означає «пісня псалма» і «синам Кореєвим», ми сказали в п’ятому розділі передмови до цієї книги. Цей псалом надписується «на кінець», бо пророцтво, що в ньому міститься, стосується кінця. Попередній, 86-й псалом пророкував про народження Христа, а цей пророкує, за словами Євсевія, про Його смерть і, за словами Афанасія, про Його зішестя до аду. Вислів «про Маелеф» поставлено замість «про ликування» (в інших списках стоїть «про ликування духовне»), бо під час співу цього псалма виступав хор. «Щоб відповідати» поставлено замість «з відповіддю», бо співали хором під супровід інструментів; тобто під час співу псалма грали й на інструменті, і, граючи на ньому, разом співали хором, тобто інструменти відповідали хору, супроводжували його. Далі в надписанні стоїть «повчання», бо від тих, хто його читає, вимагається розуміння: у цьому псалмі прихована думка про таємничу смерть Господа. Надписання «Емана, ізраїльтянина» означає, що цей псалом Давид дав ізраїльтянинові Еману: він дав його не тільки синам Корея, а й першому співцеві Еману для співу. До того ж сини Корея були співцями в одному хорі, а Еман — в іншому, тож псалом співали обидва хори, або разом, або окремо. Деякі списки мають «Етан» замість «Еман», але краще писати «Еман», як тут, а в наступному псалмі — «Етан». Бо в книзі Паралипоменон написано: і сказав Давид начальникам левитів: поставте братів їхніх співцями з інструментами, навлами й гуслами... і поставили левити Емана, сина Йоіла, а з братів його Асафа, сина Берехії, а з синів Мерарі, братів їхніх, Етана, сина Кушаї (1 Пар. 15:16–17). Нарешті в надписанні додано «ізраїльтянина» не тому, що інші співці не були ізраїльтянами, а тому, що були й чужоплемінники, тезки Емана й Етана; тому, щоб відрізнити від них, додано прикметник «ізраїльтянина».","Прим.: Феодорит каже, що цей псалом історично передрікає рабство юдеїв у Вавилоні; а «відповідь» указує на почергові повторення співу хорових відділень; і цей псалом даний синам Корея для того, щоб співали його під проводом Емана й «для відповідання», тобто для повторення піснеспіву. Ця молитва пасує й найблагочестивішим із юдеїв. Євсевій: цього Емана називає зерахітом, тобто сином Зераха, сина Юди; цей Еман, за єврейським Писанням, був у Єгипті до Мойсея. Аполлінарій називає Емана нащадком Корея, а Корей був нащадком Кегата, сина Левія."]},{"v":"2","t":["Ми сказали в 67-му псалмі, пояснюючи слова «Боже спасіння нашого», що Бог зветься спасінням замість «Бог-Спаситель», або «Бог, готовий спасати». Тут Христос як людина називає Господом і Богом Свого Отця, бо багато подібного говорить і в 21-му псалмі від Його особи. Вислів «удень і вночі» вжито замість «завжди». А постійне взивання до Бога показує віру в Бога, бо той, хто щиро любить Бога, завжди взиває до Нього — іноді устами, а іноді серцем, бо завжди потребує Божої допомоги. Або днем і ніччю називає час Юдиної зради.","Прим.: Слова Афанасія: Спаситель, як Благий, знаючи про відпадіння народу, підносить до Отця молитви за нього, щоб і він, покаявшись у злі, отримав спасіння, що дарується через Нього."],"h":"Господи, Боже спасіння мого, удень і вночі я взивав перед Тобою"},{"v":"3","t":["Під молитвою й благанням тут слід розуміти або те прохання, яке Христос промовив до Отця про Своїх учнів і про яке згадує євангеліст Іоанн у 17-му розділі, або те, яке Він приніс про те, щоб Його минула чаша смерті, і про яке згадують Матвій, Марко й Лука. Христос як людина казав ці смиренні слова так само, як промовляє їх і в 21-му псалмі. А про прихиляння божественного вуха ми сказали на початку 85-го псалма при словах «прихили, Господи, вухо Твоє й почуй мене»: як лікарі, бажаючи почути хворого, що не може говорити голосно, прихиляють вухо разом із головою до його уст, так, каже, і Ти, що живеш на висоті, прихилися до мене, смиренного, і почуй мене.","Прим.: Інший каже: отже, і ті, що перебували в крайній біді через полон у Вавилоні й немовби лежали на землі, благають Того, Хто живе на висотах, прихилити до них божественний слух і почути їхнє благання. Дидим: велика сміливість виражається словами «нехай дійде до Тебе молитва моя», ніби він бажав істинних благ, які і йому корисні, і Бог охоче їх подає, поблажливо прихиляючи вухо до того, хто просить."],"h":"Нехай дійде до Тебе молитва моя, прихили вухо Твоє до благання мого"},{"v":"4","t":["Душа моя, каже, сповнилася лиха, тобто скорбот: бо смертельно, каже, сумує душа Моя (Мф. 26:38); під адом тут слід розуміти смерть.","Прим.: Зло буває двояке: одне природне й власне, як-от гріх, а друге — за нашим відчуттям, як-от усяка образа. Афанасій каже: якщо Він поніс наші гріхи й за нас скорбить, то справедливо, що й лиха сповнився; а каже це тому, що Він Божою благодаттю за всіх скуштував смерті."],"h":"Бо душа моя сповнилася лиха, і життя моє наблизилося до аду"},{"v":"5","t":["Дієслово «зарахований» означає: Я прилучений до тих, кого ховають і кого називають тими, що сходять у рів. В іншому місці ми вже сказали, що рів означає й гріб. Отже, згадані вище слова пасують до передсмертного часу Спасителя, а ці стосуються Його поховання після смерті.","Прим.: Євсевій під ровом розумів ад, до якого зійшла душа Господа після смерті.","«Я став, як людина без допомоги»","Не сказав «як людина», бо Він був досконалою людиною, а з додатком: став, як людина безпорадна. Так і написано, що всі (учні), залишивши Його, розбіглися (Мф. 26:56). Отже, Господь видався людям немовби безпорадним, хоча Він сказав Петрові: чи ти думаєш, що Я не можу тепер ублагати Мого Отця, і Він дасть Мені понад дванадцять легіонів ангелів? (Мф. 26:53)."],"h":"Я зарахований до тих, що сходять у рів"},{"v":"6","t":["Я, каже, був вільний у гробі від тління й розпаду Мого тіла. Або це означає, що Я один зійшов до аду добровільно, а не був туди зведений іншими. І тут слід мати на увазі дієслово: Я був серед мертвих вільний; бракує тільки члена, інакше кажучи: Я, Який був вільний, без Моєї провини зійшов до мертвих; бо всі інші люди мають причину своєї смерті в гріху, адже смерть — це покарання за гріх; а один Христос був без провини й гріха. Або Христос зветься вільним через те, що всі інші люди помирали неминуче, а тому були поневолені смерті й страху смерті, як каже Павло: ті, що через страх смерті ціле життя були під рабством (Євр. 2:15); а Христос помер добровільно, тому й каже: владу маю покласти душу Мою (Ін. 10:18). Або ще інакше: Христос вважається вільним тому, що не зв’язаний кайданами аду, а вільно й з власної влади ввійшов у нього; або, краще сказати, і інших звільнив від кайданів. До того ж Христос вільний і від смертності й смерті як Бог.","Прим.: Тому й божественний Кирило сказав: тоді як усіх — і доброчесних, і лихих — хтось відводить до аду, як Лазаря — ангели, а безумного багача — ті, що забирали його душу, Я кладу її Сам від Себе. Бо один Ісус і помер, і був ведений на смерть, за словами Ісаї, за гріхи народу, і, ставши мертвим, був один вільний, бо не мав гріха, який тримав би Його; тому й казав: владу маю покласти душу Мою і владу маю знову прийняти її. У інших це приписується Афанасію.","«Як поранені, що сплять у гробі, яких Ти вже не згадуєш і які від руки Твоєї відкинуті»","І тут слід мати на увазі дієслово «Я був»: Я, каже, був, як поранені, що лежать у гробі. Симмах переклав: як поранені, що лежать у гробі, — яких, каже, Ти, Отче, більше не згадуєш, так що вони гниють і обертаються на порох, і які позбулися Твоєї допомоги за свої гріхи. Отже, Я, каже, уподібнився до таких на думку людей, але насправді Я не був таким: бо хоча Я пробитий цвяхами й списом і покладений у гріб, але не забутий у Тебе, Отче Мій! Бо Ти не даси Своєму преподобному побачити тління (Пс. 15:10), і Я не позбувся Твоєї руки, тобто допомоги; бо за незлобливість Ти прийняв Мене (Пс. 40:13).","Прим.: Слова Афанасія: і після поранення й покладення в гріб Ти згадав Мене, бо Я воскрес, подолавши смерть. І Моє тіло й після смерті було сповнене животворчої сили; тому воно водночас виточило з ребра і кров, і воду: першу — як доказ людини, а другу — на доказ того, що вище за людину, бо неможливо, щоб це сталося з мертвих тіл."],"h":"Серед мертвих вільний"},{"v":"7","t":["Найглибшим ровом Господь називає гріб, глибину якого в Євангелії Він назвав серцем землі. Далі: поклали, каже, ті, що служили Моєму похованню, — Йосиф і Никодим; темними місцями називає місця гробу, бо, коли на гроб поклали камінь, у місцях гробу настала темрява. Ті самі темні місця гробу називає тінню смерті, виражаючи одну річ різними словами, бо й темрява зветься тінню.","Прим.: Феодорит каже, що це пасує й до тих, що були у Вавилоні, і до всієї людської природи, бо всі після гріха зазнавали бід усякого роду. Так, після порушення заповіді на тих, хто живе на землі, були допущені смерть, сум і сльози, стогони й ридання, вдівство й сирітство, злидні, жорстокість та інші незліченні й нестерпні біди, що наводять на них темряву. Бачите, яке велике зло — непослух! Він не тільки відлучив від Бога, а й оточив такою безліччю лиха. А Євсевій найглибшим ровом називає найглибші краї аду."],"h":"Поклали мене в рові найглибшому, у темряві й тіні смертній"},{"v":"8","t":["Симмах переклав: обтяжив. Гнів, каже, Твій, Отче Мій, який люди своїми гріхами розпалили на себе, обрушився на Мене. Але Я, прийнявши удар, тобто ураження ним, припинив його, бо, постраждавши й померши за них, Я зупинив Твій гнів, як зупиняє гнів батька той, хто бере на себе удари, що їх батько завдає синові, за словами Євсевія. Тому й написано: ранами Його ми зцілилися; і ще: і Господь віддав Його за наші гріхи (Іс. 53:5–6). Хвилями (висотами) називає навалу спокус, яких зазнав Господь. Назвав їх Божими тому, що з волі Отця вони спіткали Його заради спасіння людей. А «всіма» ці спокуси називає, бо розуміє ті, що були Тобі завгодні.","Прим.: Слова Афанасія: люттю Божою називає прокляття смертю, наведене на людський рід. Оскільки Він став за нас прокляттям, то каже, що лють Божа затвердла на Ньому.","Прим.: Феодорита: сказав це, перенісши образ із тих, хто зазнає корабельної аварії й терпить численні наскоки хвиль і багато натисків вітрів."],"h":"На мені затвердла лють Твоя, і всі хвилі Твої Ти навів на мене"},{"v":"9","t":["Євангеліст Лука пише: стояли віддалік усі знайомі Його (Лк. 23:49). Сказав «Ти віддалив», бо це було з волі Отця.","Прим.: За поясненням іншого тлумача, подібне сказано Богом Отцем про Христа й у Захарії: ураджу пастиря, і розпорошаться вівці, тобто допущу, щоб був уражений. В історичному значенні й ті, кого відведено до Вавилона, позбулися знайомих і родичів, бо через полон одних розпорошено в одному, а інших — в іншому місці; а всі люди, що жили в нечесті, за словами Феодорита, не мали піклування ангелів.","«Зробили мене огидою для себе; я виданий і не виходив»","Юдеї, каже, дуже гидували Мною й ненавиділи Мене, тому й донині, як каже Афанасій, ненависне їм ім’я Христове. Я був виданий юдеям Юдою Іскаріотським; і хоча мав змогу вийти, тобто піти чи втекти з їхніх рук, Я цього не робив, а добровільно переніс усі муки, яких вони Мені завдали."],"h":"Ти віддалив від мене знайомих моїх"},{"v":"10","t":["Очі Мої, каже, ослабли від убогості, Отче Мій, тобто через рясні сльози виснажилася їхня природна повнота й вологість. Бо як Господь плакав над Єрусалимом, про що каже євангеліст Лука: і, побачивши місто, заплакав над ним (Лк. 19:41), так, слід думати, Він плакав і над загибеллю Юди, і над відкиненням юдеїв, і над покаранням тих, що загинули, за словами Євсевія й Діодора. Деякі під убогістю розуміють тут надмірне виснаження тіла Господнього від страждань.","Прим.: Господь плакав чотири рази: 1) коли мав воскресити Лазаря; 2) коли прийшли побачити Його елліни, що прийшли до храму (на поклоніння), і тоді Він сказав: тепер душа Моя стривожилася; і що Мені сказати? Отче, спаси Мене від цієї години (Ін. 12:27); бо ця тривога означає плач, як досить ясно каже про це й апостол: Він у дні Свого тіла з сильним голосінням і сльозами приніс молитви й благання Тому, Хто міг спасти Його від смерті (Євр. 5:7), і згідно з цим каже й тлумач апостола Павла святий Феофілакт; 3) плакав, коли побачив здалеку місто Єрусалим, за розповіддю Луки: і, побачивши місто, заплакав над ним (Лк. 19:41); 4) коли свідчив про Юду: сказавши це, Ісус стривожився духом, і засвідчив, і сказав: істинно, істинно кажу вам, що один із вас видасть Мене (Ін. 13:21); і ця тривога теж є плачем, як каже божественний Золотоустий: шкодуючи за зрадником, Господь плакав.","Прим.: За іншим тлумачем, Господь каже це й про учнів, яких Він шанував, як Свої очі: що й вони знемогли під час страждання, бо були ще вбогими й недосконалими настільки, що казали: а ми сподівалися, що це Він має визволити Ізраїля. В історичному значенні ці слова стосуються й полонених юдеїв; тому й Симмах переклав: око моє виснажилося від лиха, бо (за словами Феодорита) у сльозах я виснажив очі мої, змушений плакати від печалі.","«Я взивав до Тебе, Господи, увесь день, простягав до Тебе руки мої»","Завжди, каже, Я взивав до Тебе, Господи, тримаючи руки розпростертими в молитві не тільки за Себе як людину, а й за Моїх учнів і за народ."],"h":"Очі мої знемогли від убогості"},{"v":"11","t":["Цими словами Господь показує, що за законом людської природи Він боїться смерті, тому й просить продовжити ще життя. Так і в Євангелії каже: Отче Мій, якщо можливо, нехай мине Мене ця чаша (Мф. 26:39). Ці слова (Давида) узгоджуються зі сказаними в 29-му псалмі: чи сповідуватиметься Тобі порох? Чи звістить істину Твою? — там і шукай. Отже, Він каже: невже Ти, Отче Мій, твориш чудеса для нечутливих мерців, як твориш їх для живих? Чи лікарі воскресять мертвих, і вони, воставши, прославлятимуть Тебе? Без сумніву, ні; а живі люди, що розуміють такі чудеса й дякують Тобі за них.","Прим.: Слова Афанасія: тут показує нам причини Свого сходження до смерті, ніби кажучи так: оскільки неможливо ні для мертвих чинити чудеса, ні лікарям воскресити, щоб вони сповідувалися Тобі, ні тим, що в загибелі, пізнати істину, то тому Я, Отче, прилічений до тих, що перебувають в аді, щоб ті, хто живе в землі забуття, воскреснувши, пізнали Твої чудеса, і ті, що колись були в темряві, звіщали Твою істину. Слова безіменного: ніхто, каже, не розповість безнадійним про Твою милість, що звіщається живим, ані тим, що гинуть, тобто чинять діла, які ведуть до загибелі, про Твою істину. Бо розповідають про милість тим, хто звичайно отримує милість, а це ті, що милують ближніх; бо блаженні, каже, милостиві, бо вони будуть помилувані; і про істину — не в загибелі, а тим, хто перейшов із неї до спасіння. А темрява — це ті, ким заволоділи надмірне зло й незнання. Далі земля забуття — це серце, сповнене терну насолод і життєвих турбот. Отже, як можуть такі пізнати чудеса істини, тобто правду, яка є діяльною й моральною чеснотою?"],"h":"Хіба для мертвих Ти твориш чудеса? Чи лікарі воскресять, і вони сповідуватимуться Тобі?"},{"v":"12","t":["І ці слова містять ту саму думку, що й сказані вище. Тут загибеллю назвав гріб, як такий, що губить і руйнує покладене в нього мертве тіло. І вище ми сказали, що ті самі думки Давид у багатьох місцях виражає різними словами, а особливо коли говорить про речі плачевні й бажані. Не відчуває, каже, мертва людина Твоєї милості, Отче, а жива, яка й розповість про неї людям; так само жива відчуває й істинність Твоїх слів і те, що Ти істинний Бог, як ми сказали в 29-му псалмі, пояснюючи слова «чи сповідуватиметься Тобі порох, чи звістить істину Твою»."],"h":"Хіба хтось у гробі розповість про милість Твою і про істину Твою в загибелі?"},{"v":"13","t":["Знову й темрявою називає тут місце в гробі; те саме гробове місце розуміє й під землею забуття, тобто забутою людьми, бо гробова земля сповнена тління й смороду; і забутою в Бога, бо в Нього вже не живе той, кого в ній поховано. Живі тільки ті, кого пам’ятає Бог. А в усіх згаданих словах міститься та сама думка, і все слід читати запитально.","Прим.: Інший: оскільки, каже, Отче, мертві не можуть творити чудес, то тому Я прилічений до аду, щоб ті, хто в землі забуття і колись були в темряві, воскреснувши, розповідали Твою істину. І це збулося на ділі, коли встали багато тіл спочилих святих."],"h":"Хіба пізнаються в темряві чудеса Твої і правда Твоя в землі забуття?"},{"v":"14","t":["І я, каже, взивав до Тебе, Господи, разом з іншими людьми, бо і я людина. А каже «вранці», розуміючи те, що молитва моя скоро досягне, бо не перешкоджатимуть її вислуханню гріхи.","Прим.: Слова Євсевія: ці слова показують, що молитва Спасителя, у якій говориться «Ти ж, Господи, підійми Мене», здійснилася вранці, коли Він, як засвідчено, воскрес. За словами Феодорита, ці слова в історичному значенні стосуються й вавилонських полонених. Ось його слова: бо, бажаючи в цьому житті звільнитися від бід, що мене обтяжують, у скорботі благаю й молитвою випереджаю ранок."],"h":"А я до Тебе, Господи, взивав, і вранці молитва моя випередить Тебе"},{"v":"15","t":["Ці слова, сказані від особи Христа, узгоджуються з тими, що є в 21-му псалмі: Боже, Боже мій, почуй мене, нащо Ти покинув мене? — і з цими: Боже мій, кликатиму вдень, і Ти не почуєш мене. Це Господь каже й про нас, що раніше були відкинуті від Бога за наші гріхи. Душею Господь називає тут і Свою душу, і душу кожної людини, а Собою — кожного з нас. Чому, каже, Отче, ще відкидаєш людей і відвертаєшся від них, коли Я за всіх страждаю й плачу за них належну ціну покарання?","Прим.: Слова Афанасія: Господь молиться за народ, а ті, що через надмірну порочність виявляються негідними спасіння, роблять Його молитву за них немов безсилою. Дидима: ці слова — «нащо Ти відкидаєш душу мою, коли Я ні в чому не згрішив?» — личать сміливості Ісуса. Отже, прийнявши її, спаси тих, за кого Я молюся Тобі, і осяй їх лицем Твоїм."],"h":"Нащо, Господи, відкидаєш душу мою? Відвертаєш лице Твоє від мене?"},{"v":"16","t":["Григорій Богослов у слові на Різдво Христове каже: і Багатий убожіє, убожіючи моїм тілом, щоб мені збагатитися Його Божеством. І Сам Христос сказав про Себе книжникові слова, що показують Його велике вбозтво: лисиці мають нори, і птахи небесні — гнізда, а Син Людський не має де голову прихилити (Мф. 8:20). А в трудах Господь був від юності Своєї, бо ще від самих пелюшок терпів злі задуми й переслідування від Ірода та юдеїв. Трудами тут називає біди.","Прим.: Слова Феодорита: юність Ізраїля — це вихід з Єгипту, а всіх людей — життя поза раєм після порушення заповіді. І ті, й інші весь цей проміжок часу проводили в бідах.","«Піднісшись, я впокорився й знемігся»","Коли, каже, Я піднісся через учинені Мною, за словами Феодора, знамення й чудеса, тоді Я, на думку юдеїв, упокорився через безчестя, наругу й страждання. Або каже: коли Я був піднесений на хрест, тоді впокорився через покладення, за словами Афанасія, у гріб і сходження до аду. Понад те, Я, на думку євреїв, знемігся; бо їм здавалося, що Господь був у скруті, як позбавлений допомоги; тому й казали: стривай, побачимо, чи прийде Ілля спасти Його (Мф. 27:49)."],"h":"Убогий я і в трудах від юності моєї"},{"v":"17","t":["Гнівами й страхіттями Божими Христос називає ті, що були проти грішників: гнівами — бо вони пройшли й проникли саме Його серце, а страхіттями — бо збентежили Його. Оріген під гнівами й страхіттями Божими розуміє демонів: гнівами — бо гніваються на людей, Божими — бо вони вселяють у душу страх. Отже, Господь каже, що під час Його страждання такі страхіття проникли в Нього й збентежили Його як людину.","Прим.: Євсевій каже: оскільки вочоловічений Господь являє в Собі особу всього дуже грішного людства, бо Він прийняв на Своє тіло гріхи всіх людей, то тому по Ньому пройшли всі гніви за різні гріхи, проте не так, щоб вони мали якусь силу над Ним, а лише бентежили Його, бо Він не пізнав гріха."],"h":"Наді мною пройшли гніви Твої, страхіття Твої збентежили мене"},{"v":"18","t":["Господь сказав і в 21-му псалмі, що оточили Мене численні телята, тучні бики обступили Мене, тобто юдеї; а тут каже, що вони оточили Його, як вода, бо вода з усіх боків покриває того, хто впаде в неї. Під цілим днем розуміє день страждання; а «разом» сказано замість «усі разом»."],"h":"Оточили мене, як вода, увесь день обступили мене разом"},{"v":"19","t":["Ти, каже, Отче Мій, віддалив від Мене Моїх учнів через біду, якої Я зазнав через наругу й страждання. І вище сказав Господь: Ти віддалив від Мене знайомих Моїх. Другом, ближнім і знайомими називає Своїх учнів: другом — згідно з цими словами: ви — друзі Мої (Ін. 15:14); ближнім — бо учні перебували з Ним; а знайомими — бо пізнали Христа й були знані Христом.","Прим.: Слова Афанасія: стражданням указує на час страждання. Отже, Він каже, що під час страждання Його покинули й друзі, і знайомі. Ісихій: знайомими й друзями називає Юду та юдеїв. Сказав «через страждання», означаючи ним те страждання, яке терплять ті, що згрішили. Ісус прийняв страждання, бо являв особу людини, що каже: нещасна я людина! Хто визволить мене від цього тіла смерті? Знайомі — це юдеї з обрізаних; друг — Юда й інші учні: Я, каже, назвав вас друзями, бо сказав вам усе, що чув від Отця Мого.","Таке прикладення має цей псалом до Христа. Але він пасує й усім благочестивим, що перебувають у скорботах, і прикладається так. Господи, Боже спасіння мого, завжди взиваю до Тебе, просячи в Тебе допомоги. Подальше саме собою ясне. Оскільки душа моя сповнилася скорбот і болю, так що я близький до смерті, бо знемігся, то я, з огляду на лють проти мене людиновбивць-демонів, зарахований до мертвих. Я був легко переможений ними, бо залишився без допомоги, і, як вони бажали, був немовби мертвий; і хоча я ще вільний від смертності, бо насправді ще не помер, я став подібний до поранених і тих, що в гробі, бо мене вразили стріли гріха, або печалі. Так відповідно до цього прикладаються до християнина й інші слова. Демони кинули мене в глибокий рів гріха й темряву скорботи, яка є тінню й подобою смерті через гіркоту, що в ній. На мені затвердів гнів Твій, бо якби Ти не гнівався на мене, скорботи не перемогли б мене. До того ж Ти Своїм допущенням навів на мене всі хвилі скорбот.","Прим.: Слова Феодорита: це личило говорити не тільки юдеям і всім людям до явлення Спасителя, а це й молитва, що пасує й відповідає всім, хто перебуває в подібній біді; бо, за словами божественного апостола, усе, що було написано раніше, написано нам на повчання, щоб ми через терпіння й утіху з Писань мали надію.","Ти віддалив моїх знайомих, тобто святих ангелів, які, будучи до гріха щирими моїми друзями й знаючи мене, після гріха погидували мною; і так я відданий скорботам і від них не втікав, тобто не звільнявся, а був міцно тримуваний у їхніх кайданах. Вислів «очі мої знемогли від убогості» прикладається до кожного християнина, як ми пояснили вище. Але я завжди взивав до Тебе, прикликаючи Тебе на допомогу. І, вставши зі свого ложа, я насамперед підноситиму до Тебе молитву. Для чого Ти, Господи, відкидаєш мою душу, або, коротше кажучи, того, хто перебуває в нужді й старанно молиться Тобі? Це питання й інші так само прикладаються до кожного. Далі: я вбогий і бідний, бо не маю ні з якого боку жодної допомоги й перебуваю в трудах і скорботах через свої гріхи. Далі: коли я піднісся, як створений за образом Божим, тоді впокорився, втративши гідність образу Божого через гріх. Або й так: оскільки я піднісся від гордості, то й упокорився, упавши в прірву; і я знемігся, бо не здатний нічого робити. Наді мною пройшов, тобто мене спіткав, Твій гнів, бо я був караний за свої гріхи потопом печалі. Понад те, і страхіття Твої збентежили мене, погрожуючи мені вічним покаранням, і вони оточили мене, як вода. Або й демони, і скорботи, завжди пригнічуючи мене, панують наді мною всі разом. Ти, нарешті, віддалив від мене й знайомих, і друзів із людей, які почали уникати мене через страждання й біду, що мене спіткали."],"h":"Ти віддалив від мене друга, і ближнього, і знайомих моїх через біду мою"}],"88":[{"v":"0","t":["Повчання Етана, ізраїльтянина","І це надписання пояснено в надписанні попереднього, 87-го псалма; там і можеш це побачити. У цьому псалмі Давид розповідає про свої власні обставини й хвалить Бога як свого благодійника, а водночас уміщує й те, що стосувалося Христа, пророкуючи, за словами Афанасія та Євсевія, про Його народження, царство й страждання. Тому псалом і має надписання «повчання»: щоб розуміти розсіяні в ньому пророцтва про Христа, читачам потрібне розуміння. У ньому є також пророцтво про полонення євреїв вавилонянами.","Прим.: Слова Феодорита: блаженний Давид, бачачи, що неправдивих богів ушановано присвяченням їм храмів і що тільки ковчег Божий залишався без цієї пошани, дав обітницю збудувати божественний храм. Бог прийняв цей його намір, віддячив йому доброю обітницею й обіцяв улаштувати з його стегон Собі словесний храм, через нього звершити спасіння всіх людей і дати йому безконечне царство. Ці обітниці дав йому Бог через пророка Натана, що ясно показує історія Паралипоменон (1 Пар. 17). Дивлячись на ці обітниці, його нащадки, бачачи, що вони стали полоненими й що їхнє царство зруйноване, нагадують Богові про всі Його обітниці. Тому й пророча благодать склала на їхню користь цей псалом, навчаючи, як слід умилостивлювати Бога й користуватися Його людинолюбством. Євсевій каже, що цей псалом не надписується ні псалмом, ні піснею, і він, здається, є піснею духовною, що вимагає божественного розуміння, бо слова «милість Твою, Господи, повіки оспівуватиму» також є пророцтвом, оскільки сказано: звіщу істину Твою."]},{"v":"2","t":["Я, каже, Господи, оспівуватиму милості, які Ти явив мені. Розлогіша Давидова подяка за них викладена й у 2-й книзі Царств. Вислів «повіки (співатиму)» означає те саме, що «завжди оспівуватиму», складаючи про них пісні.","Прим.: Афанасій каже: які це милості Господні, які Він явив нам і які ми маємо оспівувати, як не зруйнування начальств, влад і самої держави диявола та звільнення нас від гріха й смерті?","«З роду в рід звіщатиму істину Твою устами моїми»","Вислів «з роду в рід» приймається в значенні «у кожному роді», бо після смерті одного покоління людей настає інше, і так світ триває до кінця віку. Або каже ще інакше: що він передаватиме цю Божу істину роду юдейському й роду християнському, бо тільки їм Давид передає Божу істину своїми устами, під якими можна розуміти книгу його псалмів. Під Божою істиною розуміє правдиві Божі обітниці, дані Давидові: одні — через пророка Натана, як викладає про це 2-га книга Царств у 7-му розділі, а інші — безпосередньо через пророчого Духа, що жив у ньому. Бо багато обітниць дав йому Бог — і щодо підкорення його ворогів, і щодо насіння, під яким євреї розуміють Соломона та його нащадків, а ми, християни, — Христа, як буде сказано далі.","Прим.: Слова Афанасія: істина Отця — це Син, Чиє ім’я з роду в рід святі промовляють своїми устами. А це слово — немов від особи апостольського лику."],"h":"Милості Твої, Господи, повіки оспівуватиму"},{"v":"3","t":["Сказав «збудується» замість «буде»: Ти, каже, Господи, сказав мені, що завжди буде милість із Тобою. Євреї кажуть, що буде милість із Давидом, яка полягає в подаванні йому допомоги від Бога, а ми кажемо, що буде милість із вірними християнами, бо слово «завжди», або «повіки», не пасує Давидові, адже він помер, а християнам дуже пасує, бо Ісус Христос став для них постійною й вічною милістю, Який збудувався й несказанно утворився з чистих кровей Пресвятої Діви Богородиці. Бо домом зветься людська природа, прийнята Богом Словом: премудрість, каже, збудувала собі дім (Прит. 9:1).","Прим.: Слова Афанасія: милість велика й дивна збудується, тобто приготується, або зведеться. Бо те, що будується, немов зводиться й постає; а це — спасіння й благодать через Христа. Дидим: можливо, милість будується, коли премудрість будує собі дім, бо її вочоловічення — це основа й кінець устроєння милості.","«На небесах приготується істина Твоя»","Істина Божа — це Христос, як неложний; так Він Сам сказав: Я — істина (Ін. 14:6). Ця-то, каже, істина утвердиться на небесах, бо дієслово «приготується», за словами Діодора, у євреїв часто означає «поставиться» або «утвердиться»; тому й Симмах замість «приготується» переклав «утвердиться». А що Христос утверджений на небесах, про це в іншому місці каже той самий Давид: сказав Господь Господеві моєму: сядь праворуч від Мене (Пс. 109:1).","Прим.: Інший каже, що обітниця, дана Давидові, божественна й небесна, а не земна й тілесна, як можуть думати юдеї. Або вислів «на небесах приготується істина Твоя» сказано замість «Ти обіцяв ділом підтвердити істинність Своїх слів». А оскільки, поки ми на землі, ми бачимо божественні речі як у дзеркалі, у загадці, ще не здатні чистим поглядом їх збагнути, то тому істина приготовляється на небесах, коли, за словами Дидима, лицем до лиця дивитимемося на цю красу."],"h":"Бо Ти сказав: повіки милість збудується"},{"v":"4","t":["За словами Феодорита, ці слова промовляються від особи Бога й Отця. Заповітом називає тут заповіт і обітницю, а вибраними — Авраама, Ісаака і Якова, за словами Афанасія та Євсевія, бо Бог обіцяв їм зростити й піднести їхнє насіння, тобто потомство. І апостол Павло каже, що Авраамові були дані обітниці й насінню його. Не сказано «і нащадкам», ніби про багатьох, а як про одного: і насінню твоєму, яке є Христос (Гал. 3:16).","Прим.: Тут слід мати на увазі спільне дієслово «Ти сказав», тобто, за словами Никити: Ти сказав: Я уклав завіт. Слова Євсевія: Ти обіцяв також Давидові подібне в книгах Царств і Паралипоменон (2 Цар. 7:12; 1 Пар. 22:9), про що й Петро, нагадуючи юдеям, каже в Діяннях: будучи пророком і знаючи, що Бог із клятвою обіцяв йому з плоду його стегон за тілом підняти Христа й посадити Його на його престолі (Діян. 2:30)."],"h":"Я уклав завіт із вибраними Моїми"},{"v":"5","t":["«Я поклявся Давидові, рабові Моєму»: Я поклявся, каже, тобто з запевненням обіцяв. Бо клятвою Божою давні називають вірну обітницю; адже й та клятва, яку промовляють люди, є не що інше, як запевнення. Я, каже, обіцяв із запевненням, що приготую, тобто утверджу, твоє насіння повіки віків. Насіння Давида за прямим значенням слова — це Соломон, а у вищому значенні — Ісус Христос, бо Він народився від насіння Давида, тобто від Святої Діви, яка є насінням Давида, як така, що походить від Давида. Бог і Отець утвердив Христа, зробивши Його вічним у Його царстві: дана, каже, Мені всяка влада на небі й на землі (Мф. 28:18). Про Нього сказав і Даниїл: і дано Йому владу, і честь, і царство, і всі народи, племена й мови служитимуть Йому; влада Його — влада вічна, і царство Його не зруйнується (Дан. 7:14). Це не пасує Соломонові.","«І збудую з роду в рід престол твій»","Збудуванням тут Бог називає збільшення й удосконалення, а престолом — царство. Зауваж, читачу, що Бог царство Христове назвав царством Давида; це тому, що Христос за тілом походив від Давида. Так і в нас є звичай царство сина називати царством його батька через природну єдність сина з батьком і, навпаки, батька з сином.","Прим.: Бог дав Давидові через Натана обітницю такими словами: поставлю насіння твоє після тебе — того, хто вийде з твого лона, — і утверджу царство його; він збудує Мені дім для Мого імені, і Я поставлю престол його повіки (2 Цар. 7:12–13). До цього великий Афанасій додає: ясно, що це не стосується самого Давида, бо як може стосуватися померлого? Але Христа, як того, що походить від нього й завжди живе й царює. А якщо це не (стосується) Христа, то ці слова в євреїв без значення, бо в них не залишилося ні престолу, тобто царської гідності, ні когось із насіння Давидового. Слова Ісихія: і де поклявся, як не там, де сказав йому: і буде, коли сповняться дні твої і ти спочинеш із батьками твоїми, Я поставлю насіння твоє тощо. Слова Дидима: оскільки Бог вірно виявляє милість, то зображається таким, що клянеться, бо в людей зазвичай клятвою засвідчують свої слова. Отже, оскільки Бог незмінний, то Його клятва означає незмінність визначення Його ради. Діодор: оскільки Давид поклявся Господеві не дати собі спокою, доки не знайде місця для Господа, оселі для Бога Якового, то тому й Бог за його клятву віддає клятвою: поклявся, каже, Господь Давидові в істині й не відречеться від неї: з плоду лона твого посаджу на престолі твоєму (Пс. 131:11)."],"h":"Повіки утверджу насіння твоє"},{"v":"6","t":["Небесами Давид називає тут небесні сили: небесні, каже, сили дякуватимуть за ці Твої дивовижні діла, Господи! Дієслово «сповідуватимуть» тут поєднано не так, як належить: замість «сповідуватимуться», тобто «дякуватимуть за чудеса Твої», він сказав «чудеса Твої». Або під небесами слід розуміти людей, що думають про небесне й мають високе життя.","Прим.: Можливо, вислів «сповідуватимуть» тут означає не «дякуватимуть», а «звіщатимуть», тобто розповідатимуть про чудеса Твої.","«Бо й істину Твою — у Церкві святих»","Небеса, каже, дякуватимуть за істину Твою, тобто за те, що Ти правдивий у Своїх обітницях. Сполучник «бо» тут зайвий. Ці Давидові слова виражають його радість і веселощі з приводу згаданої Божої обітниці. Небесні сили дякуватимуть у церкві святих, що живуть на небесах. Про цю церкву сказав Павло: і до церкви первістків, записаних на небесах (Євр. 12:23). А люди, що думають про небесне, дякуватимуть у церкві святих, що ще живуть на землі."],"h":"Небеса сповідуватимуть чудеса Твої, Господи"},{"v":"7","t":["Вислів «на хмарах» одні переклали «на висоті», а інші — «на небесних місцях»; а на висоті й на небесних місцях перебувають ангели. Хто, каже, з ангелів дорівняється до Господа, або хто зі святих може уподібнитися до Нього? Без сумніву, ніхто. Бо синами Божими за благодаттю ми маємо вважати святих, згідно з цими словами: Я сказав: ви боги (Пс. 81:6); адже Ти — Творець, а ангели й святі — творіння. Давид каже це не тому, що порівнює Бога з творінням: так висловлюються єврейською мовою, показуючи нерівність із творінням і Божу перевагу над ним. Він тут звеличує Бога піснею за те, що Він обіцяв учинити великі й спасенні діла. А це узгоджується зі словами Ісаї: не посередник і не ангел, а Сам Господь спас нас (Іс. 63:9).","Прим.: Євсевій і Дидим кажуть, що хмарами називає ангельські сили через їхню піднесеність.","Прим.: Дидим і Євсевій під Господом розуміють тут Христа, як Бога. Христос понад усяке порівняння перевершує всі небесні сили й усіх святих, що отримали всиновлення. Ніхто з них не подібний до Нього. Як може той, хто є учасником, бути подібним до того, чиїм учасником він є? До цього Євсевій додає: коли Господь і святі будуть на хмарах, тоді ніхто з тих, хто буде піднесений на хмари, не дорівняється до Того, Хто йде з силою й славою великою на хмарах небесних. Бо хоча кожен буде піднесений із силою й славою, та не з великою; а Спаситель — із великою, як її Податель. До того ж вони — у хмарі, а Він — на хмарах, що означає панування й царську гідність. Феодорит синами Божими називає уявних богів язичницьких, як і синами людськими — людей. Ніхто, каже, не може дорівнятися до Тебе, як сказано й в іншому місці: і Господь наш вищий за всіх богів."],"h":"Бо хто на хмарах дорівняється до Господа? Уподібниться до Господа серед синів Божих?"},{"v":"8","t":["Радою Давид називає тут зібрання святих, як ми сказали й у першому псалмі, пояснюючи слова «ні грішники в раді праведних», бо в зібранні святих Бог прославляється й оспівується. Отже, Давид каже, що Бог, прославлений у зібранні святих, великий і страшний для святих; бо вони оточують Його, наближаючись до Нього через єдність у чеснотах. Бог великий і страшний для святих, бо вони достеменно знають несказанну силу й перевагу Божу. Святими ми називаємо й небесні сили, бо вони так само перебувають довкола Бога. Або, за словами святого Максима, можна розуміти й інакше. Хто оточений, той має попереду й позаду себе, праворуч і ліворуч тих, хто його оточує. Отже, оскільки й Бог має людей, що оточують Його, то позаду Нього ми маємо уявляти тих, що йдуть за Ним діяльною чеснотою; ліворуч — тих, що духовно звершили природне споглядання; так каже про премудрість книга Приповістей: а в лівій руці її — багатство й слава (Прит. 3:16). А попереду Бога — тих, що через надзвичайну любов до божественної краси сподоблюються насолоди Богом лицем до лиця й унаслідок цього обожуються.","Прим.: Інший каже: і просто довкола Бога — святі, яких не відділяє від Нього гріх, ставши між ними перегородкою й відстанню. Для них Бог великий через висоту розуму й страшний через побоювання відпасти. Слова Євсевія: Бог страшний над усіма, хто довкола Нього; бо, стоячи посеред них і супроводжуваний ними, названий прославленим, великим і страшним для них, як для тих, що наближаються до Нього й пізнають Його невимовну силу. Він страшний і для супротивників, бо погрожує їм карами й піддає їм тих, хто залишає Його божественні повеління. Дидим: як нерозумні спокушаються тим, що бачать Його в образі раба й чують Його слова «перш ніж був Авраам, Я є», так, навпаки, святі прославляють і називають Його великим і страшним; і це видно з того, що Петро немовби устами всіх каже: Ти — Христос, Син Бога живого."],"h":"Бог прославлений у раді святих, великий і страшний над усіма, хто довкола Нього"},{"v":"9","t":["Боже, каже, Царю вишніх сил, або Сильний, хто подібний до Тебе! Часто повторює це не як питання, а з подивом і здивуванням, виражаючи цим здивуванням те, що Бога ні з чим не можна порівняти. Ти сильний, каже, звершити обіцяне Тобою; тому я й вірю, що все це воістину збудеться. До того ж Ти не тільки сильний, а й правдивий і зодягнений в істину, як в одяг; тому й істина, перебуваючи довкола Тебе, ніколи не відокремлюється від Тебе. Цим Давид показує, що Бог завжди правдивий.","Прим.: Слова Феодорита: яка істота може дорівнятися до Тебе, Владико? Ти — Господь і Бог сил! Ти маєш силу супутницею Твоєї волі; усе в Тебе правдиве й вірне. Дидим: Істина — це Той, Хто сказав: Я — істина. Бо як один є премудрий, що не приймає премудрості, а породжує її, так один і правдивий, що має й істину довкола себе, не будучи її учасником, а даючи її іншим: бо в усякому задумі Отець має присутнього при Собі Сина, бо Слово є в Бога, і Бог було Слово; Отець є в Сині, і Син в Отці; і Бог, будучи світлом, має в Собі світло — Сина, як каже Даниїл: і світло з Ним (Дан. 2:22). А дієслово «є» означає вічність; тому й сказано: і відблиск світла вічного. Сказав, що істина довкола Нього є, а не була чи буде, бо сама премудрість і істина є в Слові й раді Божій."],"h":"Господи, Боже сил, хто подібний до Тебе? Сильний Ти, Господи, і істина Твоя довкола Тебе"},{"v":"10","t":["Сила моря означає сильний натиск його хвиль; отже, він каже, що Ти, Господи, владарюєш і бурханням, і тишею моря, і робиш те й інше, коли Тобі завгодно. Бо як Давид оспівав Бога в 73-му псалмі Його творіннями й великими ділами, сказавши: Ти утвердив силою Твоєю море, Ти створив усі плоди землі тощо, — так каже й тут: Ти створив тощо.","Прим.: Інший каже: ці слова показують, що Той, Хто носить у Собі образ раба, — Той самий спочатку створив вологу речовину, дав повеління на лице води, поклав морю межею пісок, сказавши йому: досі дійдеш і не підеш далі, а в тобі розіб’ються твої хвилі. Правдиво сказав, що Він владарює силою моря, коли Він заборонив морю й вітрам, і настала велика тиша. Легко Тобі, каже Феодорит, і підняти море, і вчинити тишу, бо Ти поклав йому засуви й двері й утвердив його межі, щоб воно не вийшло з них і не затопило всесвіту з людьми. Здається, морем він називає царину супротивних сил; тому, сказавши про море, він додав і про пораненого та ворогів Божих, означивши цим супротивні сили та їхнього князя й показавши поблажливість Єдинородного аж до згаданого моря. Слова Ісихія: істина, каже, Твоя — у тих, хто довкола Тебе; а ми, перебуваючи далеко від Тебе, з Твого промислу про землю й море, бачачи Твої великі діла, сповідуємо, що Ти сильний і що істина Твоя довкола Тебе. Бо Ти вгамовуєш таке велике море, поклавши йому брами й межі; і воно, служачи, як Владиці, здіймаючись, тремтить у собі й розбивається, щоб не затопити всієї землі."],"h":"Ти владарюєш силою моря, бурхання ж хвиль його Ти вгамовуєш"},{"v":"11","t":["Ти, каже, Господи, упокорив чуттєво кожну горду людину, бо Господь, каже, противиться гордим (Прит. 3:34), а мисленно, за словами великого Афанасія й Діодора, (упокорив) диявола, який загордився й тому впав, — як пораненого; бо поранені, або вражені, смиренні: болем від своїх ран вони знижують і впокорюють свою пиху. Адже Бог дав Своїм рабам (владу) наступати на зміїв і скорпіонів і на всю силу ворожу (Лк. 10:19). Феодорит та деякі інші під гордим розуміли фараона, а під ворогами — єгиптян, що потонули в Червоному морі й лежали мертві, розкидані по його берегах. Слова «раменом сили Твоєї», тобто частиною руки вище ліктя, ужив замість «міцним раменом Твоїм». Або ворогами загалом називає нечестивих і демонів."],"h":"Ти впокорив, як пораненого, гордого; раменом сили Твоєї розпорошив ворогів Твоїх"},{"v":"12","t":["Твої, каже, небеса — видиме й те, що вище за видиме, і Твоя земля, як той самий Давид каже в іншому місці: усе служить Тобі (Пс. 118:91). Про небеса ми сказали у 8-му псалмі, пояснюючи слова: побачу небеса — діло пальців Твоїх, місяць і зорі, які Ти заснував.","«Усесвіт і все, що його наповнює, Ти заснував»","І тут каже те саме, що вище. І в 23-му псалмі сказав: Господня земля й усе, що її наповнює, усесвіт і всі, що живуть на ньому; там і дивись пояснення.","Прим.: Слова Євсевія: усесвітом назвав заселену частину землі, відділивши її від пустельної й незаселеної, і додав «і все, що його наповнює», виразивши цим людський рід, що наповнює всесвіт. Повнотою всесвіту, і то особливою, без помилки можеш назвати й Церкву Спасителя, засновану Ним на камені."],"h":"Твої небеса, і Твоя земля"},{"v":"13","t":["Ісихій каже, що старозавітне Писання іменем моря називає захід. Тому книга Чисел, згадуючи коліна Ізраїлеві, каже, що одні з них стояли на східному боці скинії, інші до Лівії, тобто на південному, ще інші до моря, тобто на західному, а решта — на північному: на сході — ряди ополчення Юдиного, до Лівії — ряди ополчення Рувимового, до моря — Єфремового, на півночі — Данового (Чис. 2). Деякі (тобто маніхеї) мали називати північний і західний боки творінням лихого творця, північний — через темряву. Тому Дух Святий цими словами наперед знищує їхню оману й навчає, що й ці краї створені добрим Творцем як добрі. Зауважимо тут: коли ми дивимося на схід сонця, то попереду нас схід, позаду, за плечима, — захід, ліворуч — північ, а праворуч — південь, або полудень.","«Фавор і Хермон радітимуть Твоєму імені»","Фавор і Хермон — гори в землі обітованій. Тому Давид приховано виразив ними всю цю землю, тобто що вона радітиме імені Христа, інакше кажучи, Христові, або тому, що має ім’я від Христа. А під землею розуміємо людей, що живуть на цій землі. На цих горах іноді перебував Господь за Свого життя в тілі: на Фаворі Він преобразився, а на Хермоні воскресив сина вдови, бо на цьому Хермоні стоїть місто Наїн, де Він його воскресив.","Прим.: За словами Кирила, цими словами означає чотири сторони всесвіту: словом «північ» — північну частину землі, іменем моря — західну, іменем гори Хермоніїм, що в пустелі біля Синаю, — південь, і нарешті Фавором, що в Галилеї, — схід. Ці гори заграли від радості: Хермон — під час хрещення Господнього, а Фавор — під час Його преображення. Далі, цей самий Хермон, здається, зветься й Хермоніїмом, і Аермоном, за поясненням Золотоустого й Феодорита. Божественний Кирило називає її без розрізнення і Аермоном, і Хермоніїмом, хоча в Повторенні закону написано: і успадкували землю... до гори Сіон, тобто Хермону (Повт. 4:48). Але в книзі Паралипоменон ясно показано відмінність Хермону від Аермону; так сказано: і половина коліна Манасії оселилася від Башану до Баал-Хермону, і Сеніру, і гори Хермону (1 Пар. 5:23); і гора Аермон стоїть на сході обітованої землі разом із горами Гілеадом і Сеніром. Слова Дидима: згадав про ці дві сторони тому, що від моря, тобто з півдня (бо море лежить на південному боці Єрусалима), — єгиптяни, яких Бог, спасаючи Свій народ, покарав, а на півночі — ассирійці. Тобі, каже, легко знищити їх, тобто ассирійців, як легко було знищити єгиптян. Безіменний каже, що Фавор означає «вибраний», а Хермон — «висота світла»; бо той, хто сподобився Божого вибору й підноситься світлом, радіє імені Божому."],"h":"Північ і море Ти створив"},{"v":"14","t":["Твоя сила, Господи, найміцніша, бо раменом Божим називає Його силу, яка є Христос: Христа, каже, Божу силу й Божу премудрість (1 Кор. 1:24). Нехай, каже, зміцниться рука Твоя проти Твоїх ворогів і нехай піднесеться правиця Твоя, щоб покрити нас; рукою й правицею називає Божу силу. Давид просить подвійної її дії — що карає й робить добро, інакше кажучи, такої, яка відбила б чужих і ворогів і покрила б своїх і друзів, за словами Феодорита. Що означає піднесення Божої руки, ми сказали в 9-му псалмі, пояснюючи слова: устань, Господи Боже мій, нехай піднесеться рука Твоя.","Прим.: Слова Кирила: Єдинородний зветься й раменом Отця, як у такому місці: і рамено Господнє кому відкрилося? І рукою, як-от: і рука Твоя вчинила це; і правицею: правиця Господня піднесла мене. Отже, він каже: нехай піднесеться правиця Твоя, що чинить преславні діла, і нехай явиться славною та, що творить сили. Афанасій: Твоє, Владико, рамено відкрилося всім із силою; бо хоча Він став і людиною й був подібний до нас, але перевага величі стала явною."],"h":"Твоє рамено із силою; нехай зміцниться рука Твоя і піднесеться правиця Твоя"},{"v":"15","t":["Акила переклав: правда й суд — основа престолу Твого; а Симмах — «утвердження». Думка в цих словах така: праведний Ти Суддя, і престол Твого суду утверджений на правді й суді. Отже, під правдою й судом маєш розуміти праведний суд. Старозавітне Писання зазвичай уживає й такий спосіб вислову, у якому іменник ставиться замість прикметника, як ужито й трохи нижче в словах «милість і істина» замість «істинна милість». Або правдою називає здатність судити, а судом — сам (судовий) вирок, як і милістю називає милосердя, а істиною — саме виконання Богом Його обітниці.","«Милість і істина підуть перед лицем Твоїм»","Цими чотирма словами — правдою, судом, милістю й істиною — Давид виражає чотири дії: що Ти, Господи, за природою вмієш праведно судити й виносити вирок, милувати й справджувати Свої слова. Тому Ти праведно судитимеш людський рід, що перебуває під жорстоким впливом ворога, і винесеш суд проти омани мучителя-диявола та ідолів, і помилуєш Своє творіння, і будеш правдивим в обітницях, даних Тобою мені й Твоїм вибраним. Можна сказати й інакше: милість і істина, як сказано, підуть перед Богом тому, що ніхто не може стояти перед лицем Божим, тобто в пізнанні Його, якщо спершу не буде помилуваний і не приєднається до істинного вчення віри; бо милість і істина йдуть перед таким. А деякі відносять це до майбутнього суду, розуміючи так: Ти, Господи, — найправедніший Суддя, і на Твоєму суді милість іде перед істиною, бо ніхто не може встояти перед істиною Божих викриттів, якщо не розведе її божественна милість.","Прим.: Слова Євсевія: перед правдою й судом ідуть милість і істина, бо правда потребує милості, щоб пом’якшити покарання; інакше жодна людина не встоїть перед суворістю правди."],"h":"Правда й суд — основа престолу Твого"},{"v":"16","t":["Ми багато разів казали, що вигук — це голос перемоги. Тому Давид тут називає щасливими тих, хто вміє (злагоджено) співати Христові переможну пісню як Переможцеві диявола; інакше кажучи, за словами Афанасія, ублажає християн. Або в іншому значенні ублажає тих, хто вміє вигукувати проти невидимих ворогів — демонів, перемагаючи й соромлячи їх своїми подвигами.","«Господи, у світлі лиця Твого ходитимуть»","Лице Отця — це Син, як ми сказали в 4-му псалмі, а світло Сина — це Його заповіді; бо світильник, каже, для ніг моїх — закон Твій, і світло для стежок моїх (Пс. 118:105). Тому він каже, що християни, які знають згаданий вигук, інакше кажучи, уміють оспівувати Христа й перемагати диявола, ходитимуть у заповідях Христа — Сина Божого.","Прим.: Інший каже: у світлі Духа, що посилається через Сина, Який є лицем Отця, ходитимуть духоносці, бо їх наставляє Дух Святий на всі світлі діла."],"h":"Блаженні люди, що знають радісний вигук"},{"v":"17","t":["Християни, каже, що знають згаданий вигук, завжди радітимуть, промовляючи Твоє ім’я; бо якщо й праведна людина за кожної згадки про Бога веселиться — згадав, каже, я Бога й звеселився (Пс. 76:4), — то чи не тим більше зрадіє вона, коли й назве Його? Або й ці слова стосуються Христа, імені Якого радіють названі ним християни.","Прим.: Слова Кирила: ублажає святих апостолів за те, що вони ім’ям Христовим і Його силою чинили такі преславні діла. Це добре ім’я Христове, присвоєне нам, завжди вінчає й нас, бо від Христа ми звемося християнами. Те саме каже й Ісихій.","«І правдою Твоєю піднесуться»","Правда Отця — це Син, за висловом апостола: Який став для нас премудрістю від Бога, і правдою, і освяченням (1 Кор. 1:30). Отже, Він підніс християн і, віддаливши їх від усього земного через Євангеліє, підніс їх на небо."],"h":"І імені Твоєму радітимуть увесь день"},{"v":"18","t":["Сила християн — це Христос, бо Він їх зміцнює; а похвала Христа — це Отець. Ним Христос так хвалиться, що в кожній частині Євангелія сповідує Його Своїм Отцем і Йому приписує всі Свої успіхи.","«І з благовоління Твого піднесеться ріг наш»","Благовоління Отця, тобто Його добра воля, — це вочоловічення Сина й усе, що до нього належить. Про ріг ми сказали в 74-му псалмі: він іноді означає силу, а іноді похвалу й славу. Давид, як і в інших місцях, зараховує тут до християн і самого себе. Бо з його насіння мав походити Христос, і тому через Христа він мав поріднитися з християнами: християни — діти Христові, а Христос за тілом — Син Давидів. Або це сказано від особи християн.","Прим.: Слова Феодорита: рогом називає славу. Отже, він каже Отцеві: оскільки Ти зволив послати Єдинородного, то наша слава піднеслася, бо ми прославилися, воскреснувши з Христом (у вид. Зводі)."],"h":"Бо Ти — похвала сили їхньої"},{"v":"19","t":["Що сказав вище, те каже й тут: заступництво й допомога належать одному Господові й Святому Ізраїлевому. А Святий Ізраїлів — це Бог, як сказано і в 77-му псалмі: і Святого Ізраїлевого дратували. Так само й Царем називає Бога, бо Він за природою наш Господь.","Прим.: Безіменного тлумача: заступництво може належати й Господеві, як Тому, Хто його звершує, і святому Ізраїлеві, як тому, хто його отримує; так що святий тепер — це той, хто освячується через споглядання Його розумом. Тоді тут буде така перестановка: бо Господеві, Цареві нашому, (належить) заступництво й святому Ізраїлеві."],"h":"Бо від Господа заступництво, і від Святого Ізраїлевого, Царя нашого"},{"v":"20","t":["Слово «тоді» тут приймається як «у належний час»: Ти говорив саме те, що стосується мене, Давида. «У видінні» — замість «у відчутті», бо видіння чистіше й відчутніше за інші чуття. Так і в книзі Виходу написано: і весь народ бачив голос Господа (Вих. 20:18) — замість «відчував». Синами Божими називає пророків, як улюблених Богом за чесноту. Слід думати, що багатьом пророкам було відкрито те, що стосувалося Давида; тому Давид тут і каже це. Так і пророк Натан багато сказав йому. Що ж саме? Те, що йде далі. Утім, хоча здається, що це сказано про Давида, бо окремими рисами збігається з обставинами Давида, відкривається, що сказано це про Христа. Дивовижна благодать Божественного Духа: як легко Він поєднує з обставинами Давида те, що стосується Христа, і образом або подобою прикриває істину.","Прим.: Симмах переклав так: тоді Ти говорив через видіння синам Твоїм. Бо, за словами Феодорита, ми пізнали обітниці, дані через пророків, адже їх називали прозорливцями й видющими.","Прим.: Слова Афанасія: каже «тоді» замість «у давнину», через пророчі видіння. Ти говорив синам Твоїм (тобто покликаним до гідності всиновлення). Що ж говорив? Ось Я поклав допомогу на Сильного, тобто вклав у немічних і скривджених сатаною (думку) бігти до Сильного; а Сильний — це Христос, Якого Отець дав нам на допомогу, бо Він — Господь сил. Дидим вислів «у видінні» переклав «у розумінні», бо тільки той чує мовця, хто й розуміє; а розумний сприймає видінням розуму слова, промовлені мовцем. Досконалим же, так званим синам, Бог у видінні більше показує, ніж говорить, як написано: і народ бачив (розумів) голос Господа (Вих. 20:18). Такі видіння пророків, що бачать не чуттєво, а розумом. Давид же і сильним, і вибраним із багатьох тисяч, за висловом Пісні (Пісн. 5:10), називає Христа, бо Він помазаний Духом Святим на архиєрейство й царство і народився від насіння Давидового.","«І Ти сказав: Я дав допомогу сильному, підніс вибраного з народу Мого»","Ти, каже, Господи, сказав про Давида: Я дав Мою допомогу сильному. Сильним тут Бог, здається, називає Давида як царя, бо давні називали царів сильними й володарями. Утім, переважно сильним зветься Христос за Божеством: Христа, каже Павло, Божу силу й Божу премудрість (1 Кор. 1:24). І вибраним, здається, так само називає Давида, бо Бог вибрав його в царі з юдейського народу й підніс на висоту слави через його мужність. Але насправді Бог вибрав із юдейського народу Христа за людською природою для іпостасного з’єднання, бо Діва, що народила Його, була з юдейського народу. Він і підніс Його через з’єднання (можливо, через виснаження), тому Павло й каже про Христа: тому й Бог звеличив Його (Флп. 2:9)."],"h":"Тоді Ти говорив у видінні синам Твоїм"},{"v":"21","t":["Я думаю, що ці слова, а так само й наступні аж до слів «і в імені Моєму піднесеться ріг його», Бог сказав тільки про Давида, як каже й Діодор. Хоча божественний Кирило, Дидим, Євсевій та Ісихій відносять і їх до Христа. Я, каже, знайшов Давида, щоб він був царем, відшукавши його серед дітей Єссея; бо Бог сказав Самуїлові: Я вгледів Собі царя серед синів Єссеєвих (1 Цар. 16:1). А про помазання Давида розповідає книга Царств: і взяв Самуїл ріг з олією, і помазав його серед братів його (1 Цар. 16:13). Святою Своєю Бог назвав олію помазання як божественну, бо її готували за божественною настановою й таємниче.","Прим.: Слова Григорія Богослова: Помазаник (Христос) — через Божество, бо воно є помазанням людської природи. Божественного Кирила: Слово, будучи Богом, коли народилося за тілом від жінки й стало людиною, тоді й за людською природою отримало помазання й названо Помазаником (Христом). Ісихій: Слово, будучи Богом, народжуючись за тілом від жінки й постаючи як людина, але залишаючись, як і раніше, Богом, приймаючи для Себе помазання, названо Христом. Бо Слово, будучи Богом і існуючи як Цар перед віками, присвоїло Собі те, що належить нам, щоб і ми збагатилися тим, що належить Йому. Знову Кирило: Спаситель каже: Отець, що перебуває в Мені, Він творить діла. Це-то Отець і тепер говорить про Нього в цих словах: бо рука Моя заступиться за Нього, і рамено Моє зміцнить Його."],"h":"Я знайшов Давида, раба Мого, святою олією Моєю помазав його"},{"v":"22","t":["Рукою й раменом називає силу й допомогу від Отця, як ми говорили багато разів."],"h":"Бо рука Моя заступиться за нього, і рамено Моє зміцнить його"},{"v":"23","t":["«Нічого не вдіє» поставлено замість «не матиме користі», за звичаєм єврейської мови, як каже Дидим; так і тут. Так і в Євангелії написано: бачите, що ви нічого не досягаєте (Ін. 12:19) — замість «нічого не здійснюєте, не встигаєте». Ворог, каже, Давидів нічого не досягне у війні проти нього, і син беззаконня, тобто беззаконний, більше не завдаватиме йому зла: якщо хтось силкуватиметься заподіяти Давидові зло, то вдруге вже не силкуватиметься, раз бувши вражений Давидом. Єврейській мові властиве таке розширення, за яким сином беззаконня зветься беззаконний, сином неправди — неправедний, сином погибелі — загиблий, а синами невірства — невірні.","Прим.: Кирило, прикладаючи це до Христа, каже: хоча юдеї й сказали про Христа: ходімо вб’ємо Його й заволодіємо Його спадком, але це міркування в них і в сатани було безумне, і зусилля їхні були марні. Бо Христос ожив через три дні, подолавши смерть і полонивши ад. Отже, правдиво сказано: ворог нічого не вдіє Йому."],"h":"Ворог нічого не вдіє йому, і син беззаконня більше не скривдить його"},{"v":"24","t":["Я, каже, посічу перед його лицем усіх ворогів Давидових і здобуду перемогу над тими, що його ненавидять.","Прим.: Слова Афанасія: вороги Христові, юдеї, видані римському військові й цілком загинули."],"h":"І посічу перед лицем його ворогів його, і тих, що ненавидять його, переможу"},{"v":"25","t":["З Давидом, каже, буде, як ми сказали вище, Моя істинна милість, тобто істина Божих обітниць, і милість, що полягає в допомозі від Нього. Рогом Давида, за словами Діодора, зветься Христос, інакше кажучи, похвала й слава. Бо як ріг виростає на голові рогатих тварин і служить їм міццю й окрасою, так і Давид, як цар, був головою юдеїв, бо правителів ми називаємо головами; а від цієї голови Давидової вийшов, наче ріг, Христос, Який приніс Давидові честь і славу, подібно до того, як і ріг становить велич і славу рогатих тварин. І не лише з цих причин Христос зветься рогом, а й тому, що Він за Божеством вищий за всіх, як і роги в рогатих тварин містяться вище за всі члени. Отже, Бог і Отець каже, що ріг Давидів, тобто Христос, піднесеться в Моєму імені, тобто тим, що зватиметься Богом. Згідно з цими словами каже й у Євангелії батько Предтечі Захарія: і підняв ріг спасіння нам у домі Давида, отрока Свого, як звістив устами святих пророків Своїх, що були від віку (Лк. 1:69–70). Тут указує на зібрання пророків, яких Давид вище назвав синами Божими. А домом Захарія назвав рід Давида.","Прим.: У вищому значенні, за словами божественного Кирила, істиною називає духовне й істинне богослужіння й поклоніння, якого навчає нас Христос і яке Сам Бог Отець приймає разом із Сином. Бо істина Отця — у Христі й з Христом, тобто сила істинного богослужіння з Ним, а також і милість, тобто прощення через віру.","Прим.: Слова Кирила: богонатхненне Писання, коли приписує ріг грішникам, зазвичай називає ним гордість, а щодо праведних — славу. Отже, іменами, що дуже личать Отцеві, прославляється й Сам Син; тому Він і казав Своєму Отцеві: усе Моє — Твоє, і Твоє — Моє."],"h":"І істина Моя, і милість Моя з ним, і в імені Моєму піднесеться ріг його"},{"v":"26","t":["Іменем моря виразив острови, бо вони лежать на морі; іменем рік — суходіл, бо ріки течуть по суходолу. Далі рукою й правицею назвав владу й панування. Де ж Давид зображається володарем над усім? Ніде, у жодній частині Писання. А Христос заволодів і всім морем, і всією землею, як сказано в 71-му псалмі: і володітиме від моря до моря і від рік до кінців усесвіту. Тому під рукою й правицею слід розуміти не Давидову, а ту, що належить рогові Давида, тобто Владиці Христові.","Прим.: Слова Євсевія: у вищому значенні можеш сказати, що правиця Його покладається на ріки, бо всі, хто має стати праворуч від Нього, очищаються купіллю відродження й сподоблюються впливу Святого Духа. Далі ріками названо й народи, згідно з цими словами: ріки заплещуть у долоні. А друга рука, відмінна від правиці, тобто рука, або сила, що карає, покладена на море й на гірко-солоні хвилі життя, де перебуває й дракон; вона карає ворогів і впокорює драконів, що там перебувають."],"h":"І покладу на море руку його, і на ріки правицю його"},{"v":"27","t":["Тут бракує слова «так», яке слід мати на увазі й читати: Він кликатиме Мене так: Ти — Отець мій! Де ж Давид називає Бога своїм Отцем? Ніде. А Христос у дуже багатьох місцях Євангелія як Бог називає Його Отцем, а як людина — Богом і захисником, за словами божественного Кирила й Ісихія. Так Він сказав Магдалині: я сходжу до Отця Мого й Отця вашого, і до Бога Мого й Бога вашого (Ін. 20:17)."],"h":"Він кликатиме Мене: Ти — Отець мій, Бог мій і захисник спасіння мого!"},{"v":"28","t":["Первородним Павло називає Христа в трьох значеннях: первородним між багатьма братами (Рим. 8:29), первородним із мертвих (Кол. 1:18) і первородним перед усім створінням (Кол. 1:15). Тобто як початок нового народу, як першого, хто воскрес із мертвих до безсмертя, і як вищого за нове створіння вірних. Далі Давид називає Його високим над царями. Бо тих царів, що визнали Його Богом, Христос має в підпорядкуванні, а над тими, що Йому противляться, Він вищий. Отже, Христос високий і над вірними царями, і над невірними. А Давид не переміг усіх царів землі, бо був царем однієї Юдеї."],"h":"І Я зроблю Його первістком, вищим за царів землі"},{"v":"29","t":["Для Христа, каже, зберігатиму Мою милість, бо вона потрібна Йому за людською природою; або вона потрібна не Йому, а тим, хто народився від Нього за духом, тобто християнам, за яких Він і молиться Отцеві, ставши посередником між Богом і людьми. Нарешті вірним завітом називає дану Давидові вірну обітницю, що мала сповнитися на Христі, як сказано вище: повіки утверджу насіння твоє.","Прим.: Слова Кирила: перший завіт закінчився через свою безсилість і некорисність, бо закон нічого не довів до досконалості, маючи тільки тіні й образи й лише накреслення істини; а для нас уведено кращу надію, через яку ми наближаємося до Бога. Те саме каже й Афанасій, з таким лише додатком: для цього народу, що увірував через Христа, Я збережу милість, тобто прощення гріхів через віру."],"h":"Повіки збережу Йому милість Мою, і завіт Мій вірний Йому"},{"v":"30","t":["Насіння Христа — це євангельське слово, посіяне в душах Його учнів. Це слово перебуває повіки віків. За словами Феодорита й Діодора, насіння Христове — це також християнський народ, духовно відроджений хрещенням із кожного людського народу. Симмах замість «повіки віків» переклав «безперервно». І справді, брами пекла не здолають Церкви Христової, як сказав Христос (Мф. 16:18).","«І престол Його — як дні неба»","Престол, каже, Христового царства Я зроблю таким тривалим і твердим, що він буде, як дні неба: вони тривалі й незмінні, бо до кінця світу зберігають свої природні межі. Ці слова подібні до таких: і перебуватиме разом із сонцем (Пс. 71:5). Дні приписуються небу, бо й небо творить їх обертанням сонця по небу. Нехай тепер покажуть юдеї, скажемо з Феодоритом, яке насіння Давида поставлене повіки віків, тобто зберігається на царському престолі. Або який царський престол Давидів став незмінним? Але вони нічого не можуть сказати, бо царство Давидове закінчилося з Єхонією й Седекією. Вавилоняни, узявши їх у полон одного за одним, відвели їх до свого Вавилона: Седекію там цілком осліпили, а Єхонію поставили серед рабів. Відтоді, бо престол Давида цілком зруйнувався, ніхто вже не сідав на ньому. Зоровавель після звільнення з рабства був не царем, а тільки народним правителем юдеїв; і це псалом позначає трохи далі. Тому царство Давидове тривало в його нащадках не більше чотирьохсот років.","Прим.: Тому Феодорит робить висновок: отже, через Владику Христа насіння Давидове тривало повіки, і престол Його має безперервність. Так передрік і блаженний Ісая. Сказавши, що Дитя народилося нам, Син, і дане нам, він додає: на престолі Давида й над царством його, щоб утвердити його відтепер і повіки. Так ці слова, наперед звістивши те, що стосується Владики Христа, продовжують виклад про царів, що були в проміжку часу, який минув до Нього. Дидим: оскільки небо й земля минуть, а слова Мої не минуть, то з незмінністю Своїх слів Христос царюватиме й після того, як минуть небо й земля. Бо не про небо сказав «доки воно не мине», а про дні неба; адже й після свого минання (тобто зміни) небо триватиме, бо його минання — не те саме, що загибель."],"h":"І поставлю повіки віків насіння Його"},{"v":"31-33","t":["Якщо, каже, сини Христові, тобто християни, відроджені через Євангеліє й купіль святого хрещення, покинуть закон, і не ходитимуть у Моїх судах, і збезчестять Мої постанови, і не збережуть Моїх заповідей, то Я випробую палицею й бичем їхні беззаконня. Яку різницю мають закон, суд, правда й заповідь, ми сказали в 17-му псалмі, пояснюючи слова «бо всі суди Його переді мною». Дієслово «осквернять» поставлено замість «знищать», бо скверним зветься те, що не освячене, на відміну від святого, інакше кажучи, те, що в загальному вжитку й малоцінне. Палицею й бичем тут називає спокуси. А думка в цих словах така: Я напоумлю порушників Мого закону з-поміж християн повстаннями народів, жорстокістю правителів, голодом та іншими подібними покараннями, але не відвернуся від них зовсім. Нарешті беззаконнями й неправдами називає цілком ті самі гріхи.","Прим.: Великого Василія: тим, хто чинить гріхи, що піддаються лікуванню, у цих словах погрожує покаранням беззаконь через палицю; і ця Божа палиця, як така, що карає, робить суди твердими. А тим, хто невиліковний, Він каже: для чого вас ще бити? Бо ви зазнали всіх ран, ви знехтували всі удари, що сприяють наверненню; на вас чекає розтрощення. Бо з бід, що трапляються, одні бувають за гріхи, інші — для виправлення звичаїв тих, хто зазнає спокус, а ще інші — для розтрощення безнадійних, як було з фараоном. Останнім погрожують уже не рани й не бичі, а знищення."],"h":"Якщо сини його покинуть закон Мій і не ходитимуть у судах Моїх, якщо постанови Мої осквернять і заповідей Моїх не дотримають, — покараю палицею беззаконня їхні й ранами неправди їхні"},{"v":"34","t":["Не заберу, каже, Моєї милості від порушників Моїх заповідей, бо Я жалію їх і чекаю їхнього покаяння. Яке безмежне людинолюбство! І караючи, Бог милує й не посилає покарання, не розведеного милістю; а завдає ран і карає їх як зневажників і водночас милує як Своїх. І не пошкоджу, каже, Давидові, порушуючи завіти й обітниці, які Я йому дав. Тут сполучник «і не» зайвий, як і в наступному вірші.","Прим.: Афанасія: Симмах дієслово «не пошкоджу» висловив так: не порушу. Акила: не скажу неправди. Він каже: хоча нащадки Давидові вчинять і незліченні злочини, і Я піддам їх покаранням, але в обітниці, даній Давидові, не скажу неправди."],"h":"А милості Моєї не заберу від них і не пошкоджу в істині Моїй"},{"v":"35","t":["Тут сполучник «і не» (як сказано) зайвий. Не принижу, каже, завіту й обітниці, даної Мною Давидові. Гідність завіту — це його істинність, а відкинення й порушення його — це приниження для нього. Заповітом же називає те, що сказано вище, а саме: повіки збережу йому Мою милість. Далі слова «того, що вийшло з уст Моїх, не зречуся» пояснюють попереднє. Вислів «з уст» ужито так, як личить людині, а не Богові: бо уста, язик і рот, що приписуються Богові, — це Його слова."],"h":"І не оскверню завіту Мого, і того, що вийшло з уст Моїх, не зречуся"},{"v":"36","t":["«Раз» тут стоїть замість «твердо», як і в такому місці: раз сказав Бог (Пс. 61:12). За словами Ісихія, Він каже так: Я твердо поклявся, тобто запевняв Своєю святістю. Бо хто клянеться, той клянеться більшим; а Бог, не маючи нікого вищого, щоб поклястися ним, тому клянеться Самим Собою і Своєю святістю, як виклав це й великий Павло в посланні до євреїв (розд. 6). Вислів «чи ж Давидові скажу неправду?» означає «Давидові не скажу неправди». Бо старозавітному Писанню властиве вживання частки «чи» замість «не», коли клянуться; так ужито в таких словах: як він поклявся Господеві, обіцяв Богові Якова: чи ж увійду в житло дому мого? (Пс. 131:3) — замість «не ввійду», і подібних.","Прим.: Слова Євсевія: словом «раз» виражає вірність Свого рішення, що не підлягає зміні. Те саме каже й Ісихій.","Прим.: Слова Діодора: або клянеться Своїм Святим Отроком, як батько клянеться здоров’ям свого єдиного й улюбленого сина. Зауваж, що, за словами Євсевія, Бог зображається таким, що клянеться в тому, що безперервне й незмінне. Тому, вручаючи з клятвою неперехідне священство Священикові, що був за чином Мелхиседека, не розкаюється; і Авраамові так само. А якщо колись дає щось тимчасове, то не клянеться в цьому. Наприклад, вручивши царство Саулові без клятв, Він каже: розкаююся, що зробив його царем. Тому й Давидові клянеться в тому, що Спаситель Христос народиться від його насіння; так що саме Сонце правди вічно перебуватиме, доки триватиме його (Давида, або його насіння) влада."],"h":"Раз Я поклявся святістю Моєю: чи ж Давидові скажу неправду?"},{"v":"37","t":["Насіння Давида — це Христос за тілом, як ми сказали вище. Він і царює вічно: над християнами — з їхньої волі, а над невірними — і проти їхнього бажання. Дана, каже, Мені влада на небі й на землі (Мф. 28:18). А насіння Христове — це євангельське слово й духовно відроджені ним християни, як сказано вище. Отже, і Євангеліє, і християнський народ Христів перебуватимуть, за Моєю обітницею, повіки. Понад те, і престол, тобто царство Христове над християнами, буде, каже, славним і непохитним, як сонце. Чому він бере тут сонце як образ, або подобу, незмінності, ми сказали в 71-му псалмі, пояснюючи слова «і перебуватиме разом із сонцем»: царство Христове перебуватиме доти, доки перебуватиме сонце, інакше кажучи, воно безконечне.","Прим.: За словами Кирила, престол Христів — це Церква, бо Він спочиває на ній. Отже, він каже, що Церква Христова сяятиме й просвічуватиме піднебесну, тривкою, як сонце й місяць. Бо як жодна людина не здатна погасити сонце й місячний круг, так ніхто ніколи не затьмарить сяйва Церкви, тобто її мисленної світлості. Вона світить завжди, як великі світила. Майже те саме каже й Афанасій."],"h":"Насіння його повіки перебуватиме, і престол його — як сонце переді Мною"},{"v":"38","t":["Ці слова слід читати з перестановкою так: і як повний місяць. Царство, каже, Христове славне й непохитне повіки, як місяць у повні. Досконалим назвав повний місяць, і обидва світила взяв для порівняння, як і в 71-му псалмі.","«І свідок на небі вірний»","Симмах замість «свідок» переклав «той, хто засвідчив». Отже, Давид каже, що Той, Хто засвідчив, тобто дав обітницю про моє насіння, — Бог — перебуває на небі, а тому Він і гідний віри, і правдивий; бо люди, що на землі, не виявляються гідними віри й правдивими.","Прим.: Інший каже: цими словами виражає вознесіння Господа з тілом, яке має перебувати на небі вічно, як нероздільно з’єднане з Богом Словом. Слова Євсевія: а того, що так буде, свідок є на небі, про Якого каже й Йов: і ось тепер на небі свідок мій, і Заступник мій на висотах (Йов 16:19)."],"h":"І як місяць повний — повіки"},{"v":"39","t":["Ці й подальші слова Давид каже від особи юдейського народу. Пророк плаче над полоном, якого мали зазнати від вавилонян юдеї, що думали, ніби обітниці, дані Богом Давидові, уже знищені. Ти, каже, Господи, відкинув потомство Давида, про яке обіцяв вище, і знеславив його полоном. А ці слова вказують на царів Єхонію й Седекію, відведених, за словами Давида, у полон, як ми сказали. Але дуже нерозумні ті юдеї, що думають, ніби Бог сказав неправду, бо це неможливо й безглуздо. Отже, насіння Давида, вічне у своєму царюванні, — це Христос, Чиєму царству не буде кінця (Лк. 1:33). А юдеї розуміють це про тілесний престол і земне царство, тоді як царство Христове не від світу цього, як Він Сам сказав, тобто не чуттєве, а мисленне; бо царство Христове — це покора вірних і їхнє добровільне служіння. Я, каже, поставлений Ним Царем (Пс. 2:6), і далі: і дам Тобі народи в спадщину Твою і в володіння Твоє — кінці землі (там само).","Прим.: За словами божественного Кирила, пророк говорить тут про події при чесному хресті. Отже, він каже ніби до Отця й Бога, що Ти відкинув і принизив, тобто допустив, щоб Він був відкинутий і принижений. Бо не Отець принизив Свого Сина, а зробили це юдеї, хоч і з допущення Бога й Отця. Слова безіменного: Ти, каже, повалив на землю Його славу; бо, за тим, як Він являвся беззаконним юдеям під час страждання, Він видався простою людиною; але, вільний серед мертвих, за висловом пророка, не залишився мертвим.","«Ти розгнівався на помазаника Твого»","Помазаником Божим називає царя, як помазаного на царство з Божого суду. Так і в 1-й книзі Царств (1 Цар. 24:7) Саул зветься помазаником Господнім. Каже: Ти розгнівався (відклав), тобто збив Свого царя Давида з дороги тим, що відклав і не довершив даних йому з клятвою Твоїх обітниць."],"h":"А Ти відкинув і принизив"},{"v":"40","t":["Ти знищив, каже, обітницю, дану Тобою Твоєму рабові Давидові. І в 73-му псалмі сказав: до землі осквернили оселю імені Твого. А тут святинею Давид називає славний Єрусалимський храм. Давид хотів збудувати його й залишив своєму синові Соломонові всі заготовки й креслення будівлі, бо Бог повелів, щоб цей храм збудував не Давид, а його син Соломон. І в 73-му псалмі святим, або святилищем, назвав той самий храм. Юдейський народ відносить усе своє страждання й полон до Давида з тією метою, щоб милосердям і любов’ю, яку Бог мав до Свого раба Давида, привернути Його милість до себе.","Прим.: Слова Діодора: Ти осквернив на землі святиню його, тобто Ти віддав смерті й гробу тіло Христове, або Церкву, що становила Його дім і святилище, допускаючи часом, щоб вона зазнавала переслідувань від безбожних. А раб Божий — це Христос, як Той, Хто прийняв на Себе образ раба й народився від Тієї, що сказала ангелові: ось Я, раба Господня; нехай буде Мені за словом твоїм!"],"h":"Ти зруйнував завіт раба Твого, осквернив на землі святиню його"},{"v":"41","t":["Огорожами тут називає стіни й закони, а Давидом — народ в особі царів Єхонії й Седекії, бо вони були нащадками Давида. Твердинями цих царів були фортечні стіни Єрусалима. Але коли кожного з них по черзі відвели в полон, то замість твердинь і фортечних стін їх оточили боязкість і страх. Ти, каже, Господи, колишні огорожі й фортечні стіни Давида обернув для нього на страх і боязкість, бо останнє в його нащадків є замість першого.","Прим.: За словами божественного Кирила, огорожами Христовими і Його укріпленнями називає святих апостолів; бо ті, що здавалися Його твердинями, покинули Його під час страждання й розбіглися. Те саме каже й Дидим."],"h":"Ти зруйнував усі огорожі його, обернув твердині його на страх"},{"v":"42","t":["Ті, що проходять дорогою, тобто всі сусідні з єрусалимлянами народи й ті, що проходили біля них, як-от моавитяни, аммонітяни, чужоплемінники, ідумеї та інші, — вони-то й грабували Давида, тобто багатство й усе майно Давида. Ці народи назвав тими, що проходять дорогою, і в 79-му псалмі.","Прим.: Слова Діодора: і сповнилося те, що пограбовано Христа, тобто Його тіло; бо ви, каже, — тіло Христове, а окремо — члени. А вороги Його звеличуються над Ним, ніби своєю силою завдають Йому тих бід, які Ти на Нього допустив; і цим веселяться ті, що Його ненавидять, не бачачи жодного захисту, коли вороги зібралися проти Нього на війну і, зв’язавши Його, підняли на хрест, завдаючи Йому всяких кривд.","«Став ганьбою для сусідів своїх»","Цей вірш є і в 78-му псалмі, виражений у множині так: ми стали ганьбою для сусідів наших."],"h":"Грабували його всі, що проходять дорогою"},{"v":"43","t":["Ти, каже, Господи, поставив вище за Давида вавилонян, що полонили нас, його потомство. Бо ті, хто перемагає у війні, високо піднявши руки над переможеними, б’ють їх. І Ти, каже, звеселив усі сусідні народи, як сказав і в 78-му псалмі.","Прим.: І Христос став радістю й посміховиськом для тих, що казали: спаси Себе й зійди з хреста; і багато сміялися й раділи юдеї та через надмірне незнання думали, що перемогли Його проти Його волі, і кивали на Нього головами своїми. Слова Кирила."],"h":"Ти підніс правицю тих, що гноблять його, звеселив усіх ворогів його"},{"v":"44-45","t":["Ти, каже, Господи, не даєш більше допомоги Давидові, як зазвичай подавав йому під час війни, і не допоміг йому у війні проти вавилонян. Ти припинив також звичне очищення, яке він мав. Бо юдеї у свої свята вживали кроплення й очищення; цими словами, через попереднє, юдейський народ виражає подальше, тобто що Бог знищив Давидові свята. Нарешті, каже, Ти зруйнував і престол, тобто царство Давида. А образ у цих словах узято з прикладу тих, хто, бажаючи когось скинути з царства чи з якоїсь іншої влади, перекидає його престол."],"h":"Ти відвернув допомогу меча його і не заступився за нього в битві. Ти позбавив його очищення й престол його повалив на землю"},{"v":"46","t":["Часом називає той час, коли, як Бог обіцяв, насіння Давида перебуватиме повіки віків. Отже, Ти, каже, зменшив, інакше кажучи, скоротив цей час і зробив його коротким, хоча обіцяв зробити його довгим; і так Ти посоромив Давида, бо ганьба нащадків — це ганьба праотця. А юдеї осоромлені, бо зазнали рабства й найганебніших лих.","Прим.: За словами Феодорита, Седекію, виколовши йому очі, поставили до жорен на весь решту його життя. Єхонія також став рабом. А це було дуже ганебно й безчесно. Діодор відносить до Христа й таке: тим часом вони думали, що Христа позбавлено очищення, яке Він звершив Своєю кров’ю, і що Його престол повалено на землю, хоча Бог поставив його, як дні неба. Бо, бачачи Його страждання й хрест, думали, що Його царство скінчилося, зменшилося й упало через сором, що був на хресті; про нього й апостол сказав: Він замість радості, що лежала перед Ним, витерпів хрест, знехтувавши сором. Слова Кирила: оскільки Його розпинателі думали, що Він, зазнавши цього, осоромлений і цілком позбувся буття, слави й імені, то, пояснюючи думки розпинателів, каже: Ти повалив Його престол на землю."],"h":"Ти вкоротив дні часу його, облив його соромом"},{"v":"47","t":["Ці слова подібні до тих, що читаються в 78-му псалмі: доки, Господи, гніватимешся до кінця? Чи палатимуть, як вогонь, ревнощі Твої?","Прим.: Слова Афанасія: тобто доки матиме силу зухвалість юдеїв, що бажають розп’ясти Єдинородного й нашого Спасителя?"],"h":"Доки, Господи, відвертатимешся назавжди? Чи палатиме, як вогонь, гнів Твій?"},{"v":"48","t":["Згадай, каже, Господи, для чого я отримав буття, тобто для чого створений: я створений, щоб жити й прославляти Твою велич. Тому визволи мене, Господи, від смерті, бо мертві не можуть хвалити Тебе. Ти, каже, не створив синів людських, тобто людей, марно й без користі, щоб вони загинули просто й без причини, як щось зайве й непотрібне. Ні, Ти вшанував їх Своїм образом, зробивши їх великими й славними. Тому не знехтуй нами, що бідно й жалюгідно гинемо."],"h":"Згадай, який мій склад: хіба марно Ти створив усіх синів людських?"},{"v":"49","t":["Питання «хто?» слід розуміти тут, за словами Євсевія, як «ніхто». Жодна, каже, людина не може жити, щоб не побачити смерті, тобто не зазнати її; і ніхто не може визволити своєї душі з руки аду. Під рукою аду розуміє панування й жорстоку владу аду. Отже, оскільки ми неминуче, каже, мусимо померти й оскільки таке смертне єство отримали за злочин, то уділи нам, поки живі, Твоє людинолюбство, за словами Феодорита.","Прим.: Слова великого Афанасія: ніхто, каже, не може уникнути смерті, і ніхто не здатен визволити з аду, якщо Ти, Владико, не даруєш воскресіння."],"h":"Хто та людина, що житиме й не побачить смерті, визволить душу свою з руки аду?"},{"v":"50","t":["Милостями тут юдейський народ називає ті обітниці, які Бог дав про насіння й царство Давида. Бо Бог дав ці обітниці зі Свого милосердя до людей; а називають їх первісними й давніми щодо того народу, за який просять, бо їхній праотець Давид жив на багато років раніше. Або, за словами Афанасія й Кирила, називає їх давніми милостями тому, що Бог визначив їх перед віками. Так каже Павло: і всім освітити, у чому полягає домобудівництво таємниці, захованої від віків у Бозі (Еф. 3:9). І Ісая називає їх давньою, правдивою радою (Іс. 25:1). Сказав «поклявся» замість «обіцяв із запевненням», а «в істині Твоїй» — замість «бо Ти правдивий».","Прим.: Слова Афанасія: давні милості Божі — це, каже, визначене ще перед створенням світу відтворення в нетління. Діодор: вище сказав, що милості Твої перебувають повіки й жодна Твоя обітниця не залишиться невиконаною. Але я бажаю дізнатися ту з них, що прихована від мене, і коли вона сповниться. Отже, оскільки передречення про сумне збулося, то має прийти у виконання й краще, тобто вічне Насіння й престол Давидів. Цього-то в давнину чекали пророки, а ми бачимо це нині на ділі в тому, що сталося з Господом Ісусом Христом."],"h":"Де давні милості Твої, Господи, якими Ти поклявся Давидові в істині Твоїй?"},{"v":"51","t":["Згадай, каже, Господи, про ганьбу рабів Твоїх, нас, юдеїв, якої завдають нам багато народів — і ті, що поневолили нас, і сусідні з нами, — і яку ми понесли в серці нашому. Дієслово «я носив» Акила переклав «я підняв», а Симмах — «я тримав». Лоном називає серце, бо в серці, немов у лоні, ми ховаємо і скорботи, і радощі. Тут слід зауважити, що займенник «яку» (у грецькому) узгоджено не з наступним дієсловом «носив», що вимагає знахідного відмінка, а з попереднім словом «ганьбу», за аттичним ужитком; те саме зроблено й у двох наступних віршах."],"h":"Згадай, Господи, ганьбу рабів Твоїх, яку я носив у лоні моєму від багатьох народів"},{"v":"52","t":["І тут можна мати на увазі спільне дієслово «згадай». Помазаником Божим називає царя Давида, як ми зауважили вище до слів «Ти відкинув помазаника Твого». Наступником (заміною) Давида називає Єхонію й Седекію, які царювали замість Давида й зазнавали ганьби через рабство, у яке потрапили. А подвоєння дієслова «ганьбили» виражає душевні страждання й печаль.","Прим.: За словами Кирила: заміна Христа — це Його смерть і кров, тобто ціна викуплення, дана за спасіння світу. Бо Він дав тіло замість тіла, і душу замість душі, і все єство замість цілої людини. І Афанасія: ця заміна Христова — та, яку ганьбили вороги життя, юдеї, біля хреста, проходячи мимо й киваючи своїми головами. Вони ганьбили Його, думаючи, що Ним заволоділа смерть. На думку інших, заміна Христа — це Церква, тобто християни, що вірують у Христа; бо замість юдейського зібрання Отець дав Синові Церкву з язичників."],"h":"Якою ганьбили вороги Твої, Господи, якою ганьбили наступника помазаника Твого"},{"v":"53","t":["Наприкінці цього псалма Давид навчає нас не нарікати в скорботах і бідах, що нас спіткають, а просити Бога й нагадувати Йому про Його благість, а потім хвалити й прославляти, бо Він усе влаштовує нам на користь. Благословен, каже, Бог завжди! Нехай буде, нехай буде благословен! Або: нехай буде те, що Йому завгодно; а завгодне Йому те, що корисне людям.","Прим.: Вислів «нехай буде» в єврейському Писанні читається «амінь», а в Акили — «вірно». І тут, на думку євреїв, закінчилася третя книга псалмів, що почалася з 72-го псалма й тривала досі, як ми сказали в останній примітці до передмови."],"h":"Благословен Господь повіки! Нехай буде, нехай буде"}],"89":[{"v":"0","t":["Молитва Мойсея, чоловіка Божого","Про це надписання ми сказали в 5-му розділі передмови до книги псалмів: псалом Давидів, але, за словами Феодорита, прикладається до Мойсея. Цей псалом учить, як слід молитися Богові під час скорбот.","Прим.: Афанасій і Євсевій кажуть, що Мойсей написав і передав цю молитву таємно, щоб люди з часом знали, як мають сповідуватися, зазнаючи таких бід, які спіткали юдеїв в останні часи після (мерзенного) вбивства Господа та їхньої впертості. Феодорит пояснює, що цей псалом пророкує про біди юдеїв у полоні й дає поняття про тлінність і короткість людської природи та про зміну юдеїв і людської природи на краще. Слова Ниського: «Молитва Мойсея, чоловіка Божого». Людство перебувало в кайданах гріха й, відірвавшись від єдності з Благом (Богом), осквернювалося (протилежними) пристрастями й потребувало заступництва перед Тим, Хто може покликати його із загибелі. Тож чоловік Божий стає заступником: він захищає полеглих одноплемінців і схиляє Бога до співчуття загиблим. Бо одразу немовби виправдовується перед Богом, що слухає, і каже: тільки одному Богові властиво бути незмінним і непорушним і завжди однаковим у благі, а людству, підвладному мінливості й зміні, ніяк не можливо перебувати в одному стані — ні тоді, коли воно сходить до Бога, ні тоді, коли відпадає від єдності з Богом (кращим). Тому й просить, щоб Незмінний (Бог) завжди був для заблудлого прибіжищем на спасіння."]},{"v":"2","t":["Вислів «з роду в рід» ужито замість «у кожному роді». Так переклав і Симмах.","Прим.: Слова Феодорита: (Бог) був прибіжищем юдеям не тільки в Єгипті, а й у пустелі, і за Ісуса Навина, і за Гедеона, Варака, Єфтая, Самсона, Самуїла й Давида, і через пророків, удостоюючи їх найбільшого піклування. І вся людська природа вживала ці слова, нагадуючи Богові про благодіяння всякого роду: як Він переніс Еноха; як у той час, коли всі полюбили звіряче життя, зберіг для роду іскру — божественного Ноя; як вибрав патріарха Авраама й усім народам обіцяв благословення."],"h":"Господи, Ти став нам прибіжищем з роду в рід"},{"v":"3","t":["Ти, Господи, — наше прибіжище в кожному роді, бо Ти існуєш завжди. До народження гір і створення землі й усесвіту Ти, каже, існуєш. Сказавши, що Творець існує раніше за створіння, псалмоспівець одразу додає й інше: що Він безпочатковий і безконечний. Бо слова «від віку й до віку Ти є» поставлено замість «від вічності й до вічності Ти один, і ніхто інший». У книгах Старого Завіту слово «вік» дуже часто означає «завжди». А слова «перш ніж постали гори й створено землю й усесвіт» означають одне й те саме й містять повторення, але надають мові урочистості й величі."],"h":"Перш ніж постали гори й створено землю й усесвіт, від віку й до віку Ти є"},{"v":"4","t":["Смирення в Писанні розуміється по-різному. Іноді воно ставиться замість лагідності, як у словах: навчіться від Мене, бо Я лагідний і смиренний серцем (Мф. 11:29). Іноді — замість виправлення, що походить від випробувань, як у словах: добре мені, що Ти впокорив мене (Пс. 118:71). А іноді ще в значенні руйнування, як у словах: Ти впокорив, як пораненого, гордого (Пс. 88:11). Іноді ж — у значенні підпадання під владу ворога, як і в цьому місці псалма. Не допусти, каже, Господи, обернутися на це приниження після того, як я прибіг до Тебе.","«І Ти сказав: наверніться, сини людські»","Ти, каже, сказав: наверніться, сини людські. Бо в багатьох місцях П’ятикнижжя Мойсеєвого Бог каже це. Отже, прийми нас, що навертаємося до Тебе."],"h":"Не обертай людини на приниження"},{"v":"5","t":["Це сказано також на доказ Божої вічності. Тисяча років в очах Твоїх вважається таким самим коротким часом, як у нас один день, і то вже минулий. Бо минулий день здається коротшим за теперішній. І знову: тисяча років перед Тобою — такий самий короткий час, як для нас четверта частина ночі, яку назвав сторожею нічною. Бо ті, що по черзі несуть сторожу у війську, зазвичай ділять ніч на чотири частини й кожну частину називають сторожею. Порівнявши спочатку тисячу років з одним днем, і то минулим, він додає ще й набагато коротший час, а саме четверту частину ночі. Бо ніч завжди здається такою, що минає швидше за день, через несвідомий стан сплячих, через темряву й відпочинок від праці. У Бога ж тисячоліття важить навіть менше, ніж у нас минулий день чи четверта частина ночі, бо самі роки завжди спливають, а Бог незмінний і вічний. Слово «бо» поставлено в ствердному значенні замість «воістину»."],"h":"Бо тисяча років в очах Твоїх, Господи, — як учорашній день, що минув, і як сторожа нічна"},{"v":"6","t":["Сказавши, що роки людського життя малі, хоч би наше життя тривало до тисячі років, псалмоспівець спрощує висловлену думку, кажучи, що й довший час — ніщо порівняно з Божою вічністю. Приниженням, ніщо, каже, буде переді Мною тисяча їхніх років. Пояснюючи інакше нікчемність таких років, він продовжує:","«Уранці, як трава, минає»","«Уранці» сказав тут замість «швидко», як ми бачили й в інших місцях. Швидко, каже, минуть тисяча років, як якась трава, що швидко гине.","«Уранці зацвіте й мине, увечері опаде, затвердне й засохне»","Усе це стосується швидкого в’янення трави: уранці вона цвіте, потім відцвітає, а ввечері опадає на землю; потім, позбувшись вологи, яку мала, твердне й засихає. «Уранці» й «увечері» вжито як означення часу. А щоб показати, як швидко гине трава, описує, що вона в один і той самий день цвіте й засихає. Або ж сказав це так тому, що деякі трави в один і той самий день і відцвітають, і засихають. Деякі ж стверджують, що це сказано про юдеїв, зауважуючи, що їхнє богослужіння в храмі тривало тисячу років, тобто від Соломона до розп’яття Ісуса Христа. Тоді зміст тут буде такий: ці тисяча років через їхнє беззаконня вважаються, як учорашній день, і приниження юдеїв дедалі більше зростатиме. І ми бачимо, що їхні приниження ніколи не припинялися. Можна розуміти й інакше: що ранок їхній, тобто їхній добробут, мине, як трава. А добробут їхній тривав лише за царювання Соломона, а потім вони завжди перебували в бідах."],"h":"Ніщо — роки їхні будуть"},{"v":"7","t":["«Зникли» замість «знемогли», загинули, коли Ти гніваєшся за наші гріхи. Про гнів і лють ми часто говорили, особливо в 6-му псалмі."],"h":"Бо ми зникли від гніву Твого, і від люті Твоєї збентежилися"},{"v":"8","t":["Ти поклав їх відкритими й видимими перед Собою. А оскільки вони не можуть сховатися, а завжди перед Твоїми очима, то тому завжди тільки дратують Тебе проти нас.","«Вік наш — у світлі лиця Твого»","Віком називає наше теперішнє життя. Усе, каже, наше життя відкрите для Твого погляду. Зміст той самий, що й у попередньому вірші."],"h":"Ти поставив беззаконня наші перед Собою"},{"v":"9","t":["Минули дні нашого життя, і ми вже близькі до смерті: так думати переконують мене надзвичайні біди. Бо ті, хто в бідах, зазвичай кажуть про себе, що вони вже зовсім загинули від них, і зневірюються в спасінні. Ми вже не раз казали й знову повторюємо, що частка «бо» вживається іноді в ствердному значенні, замість «воістину», іноді в розповідному, а іноді видається зайвою, як і тут; у Давидових псалмах часто знаходимо її зайвою. Нехай це, читачу, буде тобі правилом і надалі. Зайве часто повторювати одне й те саме.","«І від гніву Твого ми зникли»","Це вже казав вище; а повторює за звичаєм тих, хто випрошує милосердя.","«Роки наші вважалися, як павутина»","Дієслово «повчалися» тут стоїть замість «вважалися». А зміст буде той, що роки нашого життя ми вважаємо за павутину, яка робиться з великим трудом і існує недовго. Бо павутина через свою тонкість тчеться з великим трудом, а через свою неміцність швидко пропадає."],"h":"Бо всі дні наші збідніли"},{"v":"10","t":["Визначає тут число років, які людина може прожити. «Дні наших років», тобто наші дні, «у них», тобто в нас самих, — сімдесят років. Бо доти ми в собі, тобто володіємо собою, рухаємося власною силою. А якщо хтось буде в силі, тобто з напруженням, бо тоді насилу можна щось зробити, — проживе вісімдесят років.","«А що понад них — труд і хвороба»","Якщо ж хтось проживе понад ці роки, то через крайню слабкість його життя буде трудом і хворобою. «Труд» же поставив тут замість «біди». Інші ж тлумачі слова «а що понад них» розуміють так, що в роки після сімдесяти й вісімдесяти мало втіх, а більше горя через часті хвороби.","«Бо прийшла на нас лагідність, і ми будемо покарані»","Під лагідністю розуміє помірне Боже покарання. Назвав же лагідністю тому, що, коли порівняти його з тим покаранням і виправленням, якого ми гідні за свої вади, то це буде не покарання, а лагідність."],"h":"Дні наших років — у них сімдесят років, а коли в силі — вісімдесят років"},{"v":"11","t":["Якщо й мале Твоє покарання так подіяло на нас, то хто може знати, яка сила Твого гніву проти тих, хто не хоче виправитися? Безсумнівно, велика й нестерпна.","«І від страху перед Тобою злічить лють Твою?»","І хто знову вміє виміряти Твій гнів, тобто знати, який він? Воістину ніхто не може, бо Ти дуже страшний."],"h":"Хто знає силу гніву Твого?"},{"v":"12","t":["«Так», тобто керуючи мною в лагідності й помірному покаранні, дай мені пізнати в день суду Твою праву руку. Даси ж Ти мені пізнати її, коли поставиш мене праворуч серед Твоїх овець.","«І закутих серцем у мудрості»","І понад те ще покажи мені тоді праведників, з’єднавши мене з тими, чиї серця ще до їхньої смерті були закуті мудрістю. А початок премудрості — страх Господній. Або мудрість Божа — це розрізнення між чеснотою й вадами та слідування чесноті. Отже, ці слова слід відносити до майбутнього суду. Можна розуміти їх і щодо теперішнього часу, у значенні: дай нам пізнати Твою праву руку, тобто Твою силу, що робить добро й охороняє, а крім того — тих людей, що мудрі в ділах, які стосуються божественного; бо й я через них хочу стати розважливішим."],"h":"Правицю Твою так покажи мені"},{"v":"13","t":["Або Ти навернися до нас, від яких відвернувся через наші гріхи, або наверни до Себе нас, що блукали далеко від Тебе.","«Доки?»","Тобто доки не навернешся?","«І змилуйся над рабами Твоїми»","Змилосердься над Твоїми рабами, що бідують і взивають до Тебе."],"h":"Навернися, Господи"},{"v":"14","t":["Теперішнє життя можна порівняти з вечором і ніччю через спокуси, що в ньому трапляються, і бо про тих, хто помирає, кажуть, що вони сплять. Натомість майбутнє життя можна назвати ранком і днем через світлість і воскресіння з мертвих. Отже, каже, уранці, тобто в майбутньому житті, ми, що пішли, як сказано, за Твоїм наверненням, сповнимося від Тебе милості, зрадіємо й звеселимося. Тут минулий час поставлено замість майбутнього, як переклали Акила та інші."],"h":"Ми сповнилися вранці милості Твоєї, Господи, і зраділи, і звеселилися"},{"v":"15","t":["Тут також сказано «звеселилися» замість «звеселимося». «По всі дні наші», тобто постійно. Бо радощі майбутнього віку вічні й безперервні.","«За дні, у які Ти впокорив нас, за роки, у які ми бачили лихо»","Ти впокорив нас усяким лихом, яке спіткає праведників. А «лихо» — це скорботи й спокуси."],"h":"По всі дні наші ми звеселилися"},{"v":"16","t":["Зглянься, каже, на наших батьків і вчителів, що служили Тобі, і заради них веди їхніх синів до чесноти. Або зглянься на нас, рабів Твоїх, і не тільки нас, а й наших тілесних і духовних синів веди."],"h":"І зглянься на рабів Твоїх і на діла Твої, і настав синів їхніх"},{"v":"17","t":["Світлість Божа — це божественна благодать, що просвічує всіх, хто її причащається. А «світлість Господа» сказав замість «світлість, що від Господа».","«І діла рук наших випрям для нас, і діло рук наших випрям»","«Для нас» замість «у нас». «Діла рук», які вище назвав у множині, — це звичайні дії, що виконуються руками; про них ми молимося, щоб вони не відхилялися від правильності, тобто від належного. Під «ділом рук» в однині деякі зокрема розуміють милостиню, яку пророк згадав окремо як діло, особливо приємне Богові. А милостивий не тільки той, хто дає, а й той, хто співчуває. Бо від тих, хто не має грошей, просять лише співчуття й утіхи. Інші під «ділами рук» розуміють різні практичні діла чесноти, бо слово «руки» часто розуміється як чесноти цього роду. А під «ділом рук» розуміють саме споглядання, як більш одноманітне у своєму роді. Бо й руки певною мірою розуміються як сам розум, адже через нього, немов через якісь руки, наша душа спрямовується до чесноти й приводиться до Бога."],"h":"І нехай буде світлість Господа Бога нашого на нас"}],"90":[{"v":"0","t":["Хвала пісні Давидова. У євреїв без надписання","Про ненадписані псалми ми сказали в 5-му розділі передмови до псалмів. Цей псалом навчає, що надія має непереможну силу.","Прим.: Григорій Ниський каже: у євреїв цей псалом не надписаний, бо вони не хотіли надписання, яке вказує на пришестя Христове. Та відкидати це надписання не слід, бо воно належить сімдесятьом перекладачам, які своєю одностайністю показали, що ними керував Дух. Для нас цей псалом — хвала пісні, бо всяка хвала стосується Бога. Слова Феодорита: цей псалом навчає, що сила надії на Бога непереможна. Блаженний Давид здалеку прозрів духовними очима те, що мало статися за блаженного Єзекії, і побачив, як той з надією на Бога знищив військо ассирійців. Тому він написав цей псалом, щоб навчити людей, скільки благ дає надія на Бога."]},{"v":"1","t":["Хто, каже, живе в допомозі, яку подає йому вишній Бог, як у своєму домі, тобто хто не перебуває поза Божою допомогою й надіється лише на неї, той збережеться під Божим покровом, інакше кажучи, Бог його покриє. Богом небесним називає Бога як Творця й Владику неба. А якщо Він Бог неба, то, ясна річ, і Бог землі, і загалом усього створіння. Під Божою допомогою, за словами Афанасія, слід розуміти закон божественних заповідей, який Бог дав людям на допомогу в боротьбі проти демонів; тому й Ісая сказав: закон дав Бог на допомогу (Іс. 8:20). А живе в законі, за словами того ж Афанасія, той, хто живе згідно з метою закону.","Прим.: Слова Євсевія: в Акили й у п’ятому виданні стоїть: «той, хто сидить у таємному місці Всевишнього». Це означає твердість і безстрашність духу в божественному мужеві, що подвизається в Христі: у таїні його душі сидить Всевишній як Мешканець і Помічник. Ісихій: бачиш, яку сміливість перед Богом має той, хто живе під захистом Всевишнього? Він немов усього себе поклав на Нього й має в Ньому всю надію на своє спасіння. Дуже блаженний такий, він сповниться всякого благоденства. Так блаженний Давид співає і в іншому місці: Господи, Боже сил, блаженна людина, що надіється на Тебе. Такий, за словами Афанасія, оселиться під покровом Бога небесного. Само собою зрозуміло, що в майбутньому житті він буде співмешканцем Божим і житиме в тих самих оселях, що й Творець неба."],"h":"Хто живе під захистом Всевишнього, той перебуватиме під покровом Бога небесного"},{"v":"2","t":["Хто, каже, живе в Божій допомозі, той сміливо скаже: Ти, Господи, — мій заступник, і Ти один — моє прибіжище. І перед іншими скаже, що Він — мій Бог і я надіятимуся на Нього, тобто визнає перед іншими, що Він його Бог."],"h":"Скаже Господеві: Ти — заступник мій і прибіжище моє, Бог мій, і надіятимуся на Нього"},{"v":"3","t":["Сіті чуттєвих ловців, що ловлять людські тіла, — це засідки й тенета, поставлені потай біля дороги. А сіті мисленних ловців, тобто демонів, що ловлять душі, — це лихі напади, лихі похоті й підступи через пристрасті. Слово «бунтівне» Симмах переклав як «наклепницьке», бо таке слово сіє бунт у душі обмовленого; тому й Соломон сказав: страшне слово бентежить серце праведного мужа (Прит. 12:25). Пророк звернув цю мову до істинної людини, тобто до того, хто живе під захистом Всевишнього, і, звертаючись до неї, підбадьорює її: Господь визволить її від сітей мисленних і чуттєвих ловців, за поясненням Афанасія.","Прим.: За словами Кирила й Дидима, слово бунтівне — це слово нечестивих єретиків, бо вони бентежать серця невинних нестримним злослів’ям, не розуміючи ні того, що кажуть, ні того, що стверджують."],"h":"Бо Він визволить тебе від сіті ловця і від слова бунтівного"},{"v":"4","t":["Бог, каже, битиметься за тебе, людино, бо ти надієшся на Нього. Образ узято з того, як хтось стоїть перед іншим і, б’ючись, прикриває його своєю тінню, тобто затуляє його плечима, задньою частиною свого тіла. Бо грецьке слово означає місце між лопатками, яке звуть спиною або плечима. А плечі Божі — це Його охоронна сила, яку ще називають Божими крилами.","Прим.: Інший каже: це слово, на мою думку, означає місце трохи нижче шиї й немовби між лопатками, але не зовсім спину. Ще хтось: це місце, де між лопатками кріпляться крила. Феодорит: Він буде твоїм захисником і покриє тебе, коли битимешся. Це взято з прикладу тих, хто в бою стоїть попереду й своїми плечима затуляє тих, хто позаду. А крилами називає дії промислу, уживаючи образ птахів, які з природженої любові вкривають своїх пташенят крилами. Хтось сказав ясніше: покриє тебе в тіні Своїх крил, як пташеня. Це узгоджується зі сказаним у Повторенні закону: як орел (тобто Бог) покрив своє гніздо й зігрівав своїх пташенят, розпростер свої крила, прийняв їх і взяв на свої рамена. Те саме сказав Господь про Єрусалим: скільки разів хотів Я зібрати дітей твоїх, як птаха збирає своїх пташенят, — і ви не захотіли. Ниського: вислів «раменами Своїми осінить тебе» означає бути позаду Бога, бо плечі — позаду. Хто йде позаду Бога, той не зіб’ється з правого шляху, якщо завжди дивиться вслід Тому, Хто йде попереду. А хто рухається вбік або дивиться в обличчя своєму Провідникові, той прокладає собі нову дорогу. Тому й Мойсей дивиться не в лице Богові, а на Нього ззаду.","«Зброєю оточить тебе істина Його»","Під зброєю тут розуміється захист зброєю. Отже, Давид каже людині, що живе в Божій допомозі: якщо ти правдивий у слові й ділі, то істина оточуватиме тебе, як зброя, тобто берегтиме тебе з усіх боків. Зверни увагу, читачу, на похвалу істині: Давид каже, що вона Божа, бо властива Богові. Адже якщо брехня властива дияволові, то, ясна річ, істина, навпаки, властива Богові. Згідно з Афанасієм, можна сказати й інакше: Христос оточить і збереже хрестом, як зброєю, тих, хто живе в Його допомозі. Бо істина Отця — це Христос, як Він Сам сказав: хто бачив Мене, той бачив Отця (Ін. 14:9).","Прим.: Слова Афанасія: зброя Христова — це хрест; оточені ним, ми стаємо відважними на всяку битву й перемагаємо всякого ворога."],"h":"Раменами Своїми осінить тебе, і під крилами Його знайдеш надію"},{"v":"5","t":["Ти, каже, людино, що живеш у Божій допомозі, не злякаєшся страху, що трапляється вночі від демонів чи від людей. І не злякаєшся стріл: ні чуттєвих, що їх кидають люди вдень, ні мисленних, якими вражають демони й пристрасті."],"h":"Не злякаєшся страху нічного, стріли, що летить удень"},{"v":"6","t":["Ти, каже, що живеш у Божій допомозі, не злякаєшся нічого, що ходить у темряві, як-от злодія, підступника, палія домів. Темна річ — це розпуста, перелюб, демон пристрасті й подібне. Напасть — це будь-яка мимовільна річ, що трапляється несподівано. Полуденним демоном одні, як-от Євсевій та інші, називають демона лінощів і безтурботності, що схиляє людей лежати особливо опівдні. Інші називають так демона мерзенних і тілесних помислів, а деякі — демона нестриманості. Усі такі демони воюють проти людей опівдні, коли черево насититься й обтяжиться їжею.","Прим.: За словами Феодорита, є два види злого задуму: одні таємно й приховано, немов уночі й у темряві, непомітно готують сіті на бажану здобич, а інші — відкрито й немов удень, урочисто. Отже, страхом нічним називає приховану небезпеку, а стрілою, що летить удень, — явний задум. За словами Дидима, страх нічний — це небезпека з боку тілесних насолод, що нападає особливо в темряві. Стріла, що летить удень, — це користолюбство, бо це його час. Річ, що ходить у темряві, — це всякий гріх і незнання та злобні духи омани, що їх породжують. За словами Євсевія, напасть спіткає тоді, коли розум схиляється до насолод, коли знехтує ділами благочестя й не дбає про труди чесноти. Слова Феодорита: «біса полуденного» сказав у значенні слави, що захоплює багатьох. І зловмисники з-поміж людей зазвичай після їжі й насичення кидаються немов на готову здобич і легко поневолюють тих, кого позбавлено вишнього промислу.","Прим.: Слова Григорія Богослова: хто надіється на Господа, той не злякається й диявола, що перетворюється на ангела світла, хоч би той обіцяв яскраве світло й хоч би розбещеним здавався самим полуднем. Кирила: можливо, річчю, що ходить у темряві, називає непомітний гріх. Бо іноді ми не знаємо таємної речі; тому, роблячи інше, помиляємося й падаємо в точило загибелі. Про таких той самий Давид, молячись, каже: від таємних моїх очисти мене. Інший каже, що загалом річ, яка ходить у темряві, — це зловмисність, що виявляється там, де її не чекають, і всякий гріх і незнання; а полуденна напасть — це явна й відкрита шкода. Зауваж, що полуденний демон збентежив Давида, коли той після полуденного сну впав у перелюб із Вірсавією."],"h":"Ні речі, що ходить у темряві, ні напасті, ні біса полуденного"},{"v":"7","t":["Грецьке слово означає бік загалом. Але тут боком Давид назвав лівий, кажучи, що з лівого боку від того, хто живе в допомозі Всевишнього, впаде тисяча стріл, а з правого боку — десять тисяч стріл, і до нього не наблизяться, тобто не пошкодять його. У вищому значенні цей псалом каже: ти, що живеш у Божій допомозі, зазнаватимеш з лівого боку багатьох стріл, а з правого — ще більше. Лівий бік — це коли хтось стає мішенню для стріл безумних пристрастей, люті й похоті, які явно й незаперечно є злом. Правий — коли когось уражають причини, що видаються правими й добрими, але насправді не такі. Бо ворог-диявол знає, що багато хто не приймає гріхів, коли вони з’являються явно й у своїй наготі. Тому він починає боротьбу проти них із речей, що видаються добрими, а потім через них скидає їх і в явне зло.","Прим.: Тому й Оріген згідно з цим каже: у вищому значенні доречно сказав, що тисячі злоумишляють проти лівих, а десять тисяч — проти правих дій. Бо наші праві дії й чесноти, як сильні й дивовижніші, ворожі сили намагаються ослабити. І більше тих, хто падає через нібито праві дії, ніж тих, хто грішить явно; бо більшість людей, виправдовуючись якимись правотами, часто спокушається гріхами. Слова Ісихія: десятки тисяч нападають на праві дії, як на сильніші; утім, дуже багато хто падає більше через такі дії, що видаються правими, ніж через ті, у яких грішать явно. Феодорита: хоч би, каже, безмежна сила напала з правого й лівого боку від тебе, тобі від них не буде жодної шкоди; навпаки, ти побачиш, як вони падатимуть від божественного удару. Так було й за Єзекії: сто вісімдесят п’ять тисяч ассирійців були вражені без військової зброї. Так було й за Гедеона, і за Йонатана, і за Йосафата, і за пророка Єлисея. Згідно з цим каже й Афанасій, наводячи приклад того, що сталося за Йосафата. Той переміг не воюючи, а співаючи й хвалячи Бога такими словами: славте Господа, бо повіки милість Його (цей псалом зветься поліелейним). І прийшов Юда на сторожову вежу в пустелі, і побачив безліч; і ось усі вони лежали мертві на землі, і не було такого, хто врятувався (2 Пар. 20:24). Тому й написано, за поясненням Дидима: таємною рукою воює Господь з Амаликом з роду в рід (Вих. 17:16). Бо не перестане Господь спасати тих, хто Його любить."],"h":"Упаде з лівого боку від тебе тисяча, і десять тисяч праворуч від тебе, а до тебе не наблизиться"},{"v":"8","t":["Стріли, каже, ворогів не наблизяться до тебе, що живеш у Божій допомозі. Якщо прозриш мисленними очима, то пізнаєш, що це правда, і побачиш покарання, яке мають отримати від Бога грішники — демони й люди, що ворогують проти тебе."],"h":"Тільки очима твоїми дивитимешся і відплату грішникам побачиш"},{"v":"9","t":["Той, хто живе в допомозі Всевишнього, почувши згадані обітниці, які звістив йому Давид, з утіхи взиває, за словами Діодора, до Бога й каже: Ти, Господи, — моя надія.","Прим.: Інший каже, що тут бракує дієслова «ти сказав»; тоді думка буде ясніша: ти сказав: Ти, Господи, — моя надія!"],"h":"Бо Ти, Господи, — надія моя"},{"v":"10","t":["«Всевишнього ти зробив своїм прибіжищем?» Давид тут, відповідаючи тому, хто живе в Божій допомозі, каже: ти сказав, що Господь — твоя надія, і ти Всевишнього зробив своїм прибіжищем? Тож знай, що жодна спокуса до тебе не наблизиться. Слова «ти Всевишнього зробив своїм прибіжищем?» слід читати запитально, а слова «не прийде до тебе зло» — як відповідь, бо це відповідь на них. А що до того, хто має своїм прибіжищем Бога, не наближається спокуса, це засвідчує навіть диявол, коли взиває до Бога про Йова: хіба не Ти обгородив його й усе, що в нього? (Йов 1:10). Проте, коли Бог допустить, може наблизитися до такої людини зло, тобто біди, небезпеки й спокуси.","Прим.: Афанасій, пояснюючи слова «не прийде до тебе зло», каже: зло за своєю природою приходить ззовні, а чеснота має причину свого буття всередині (людини). Бо, за словами Еклезіаста, Бог створив людину правою, а вона, забажавши багатьох помислів, привернула до себе зло ззовні: ось що я знайшов: Бог створив людину правою, а люди почали шукати багатьох помислів.","«І рана не наблизиться до оселі твоєї»","Не тільки, каже, жодне зло не наблизиться до тебе, а навіть і до твого дому. В іншому значенні раною може бути всяка хвороба, а оселя душі — це тіло. Отже, він каже, що й до твого тіла не наблизиться хвороба за те, що ти зробив Бога своїм прибіжищем. Доречне пояснення є в Золотоустого: якщо людину Божу спіткають немочі, рани й інші подібні спокуси, то для неї вони становлять подвиг і випробування й примножують вінці, а для грішника вони стають справжніми ранами. Бо багато, каже той самий Давид, ран у грішника (Пс. 31:10)."],"h":"Не прийде до тебе зло"},{"v":"11","t":["Ці слова подібні до сказаних тим самим Давидом у 33-му псалмі: ангел Господній ополчиться довкола тих, що бояться Його, і визволить їх. І Авраам, підбадьорюючи слугу свого дому, коли посилав його до Месопотамії, сказав: Господь Бог пошле Свого ангела перед тобою (Бут. 24:7). Яків також каже: ангел, що визволяв мене від усякого зла (Бут. 48:16). З цього ми робимо висновок, що Бог через ангелів охороняє тих, хто на Нього надіється. Далі дорогами називає дії людини.","Прим.: Зауваж, за словами святого Кирила: аріани, чуючи, що диявол казав ці вірші Христові, коли спокушав Його на горі, прикладають до Христа й вищесказані слова «Всевишнього ти зробив своїм прибіжищем». Але вони погано їх прикладають, ідучи в цьому за батьком брехні, сатаною, бо думають довести, ніби Син не в усьому рівний Отцеві. Бо якщо за їхньою думкою це так, а ми своєю надією зробили Христа, Який має Своїм прибіжищем Отця, то ми прибігли до Того, Хто Сам отримує допомогу, і називаємо Спасителем Того, Хто Сам отримує спасіння від іншого. Але це зовсім не правда. Бо Всевишній — як Син, так і Отець, і Він — прибіжище й надія всіх. Сатана промовив ці вірші до всезагального нашого Спасителя Христа, як до звичайної людини. Будучи темрявою, він не розумів сили тих слів: у цьому псалмі вони промовляються від особи кожного праведника, що отримує допомогу від Всевишнього Бога, і слід розуміти, що Дух каже кожному праведникові: ти зробив Всевишнього своїм прибіжищем, не прийде до тебе зло тощо."],"h":"Бо ангелам Своїм заповість про тебе берегти тебе на всіх дорогах твоїх"},{"v":"12","t":["Руки ангелів — це їхні охоронні сили. «Понесуть» поставлено замість «підтримуватимуть під час спокус і скрутних обставин», щоб і нога твоя не спіткнулася об камінь. Під каменем можна розуміти всякий гріх і всяку перешкоду чесноті. Нарешті нога — це поведінка людини, якою ми проходимо теперішнє життя.","Прим.: Божественний Кирило каже: (Бог) велить добрим силам захищати скривджених і відступати від згубних людей не тому, що Сам почувається безсилим їх берегти, — бо як і чому могло б це бути? — а як цар доручає своїм наближеним протистояти нападам ворогів і відбивати користолюбців від тих, хто під його скіпетром. Слова Діодора: як батьки за тілом, бачачи, що дорога жорстка й непрохідна, беруть своїх дітей на руки, щоб ті не пошкодили своїх ніжних ніг, бо не можуть ходити гострою дорогою, так і розумні сили не дають понад силу страждати тим, хто ще не може зносити страждання, бо має немовби дитячий розум. Вони визволяють від усякої спокуси, щоб ті через недбальство не впали під ноги сатани й не зреклися добровільного служіння Богові. Коли диявол зрозумів ці слова погано й відніс їх до Христа, Господь, викриваючи його, сказав у відповідь: написано: не спокушай Господа Бога твого. Бо Бог обіцяв допомогу не тому, хто спокушає, а тому, хто бідує; не марнославному, що шукає порожньої слави, а тому, хто в крайній нужді. Я вже не кажу про те, що сказане псалмоспівцем стосується не Мене, Якого потребують і ангели, а праведника."],"h":"На руках понесуть тебе, щоб не спіткнувся ти ногою своєю об камінь"},{"v":"13","t":["Не наблизиться, каже, до тебе, людино, що маєш своїм прибіжищем Бога, жоден отруйний чи хижий звір, як це ясно відкрилося на багатьох святих, про що розповідають їхні житія. У вищому значенні наступанням на отруйних і хижих звірів і їх потоптанням Давид виразив перемогу над злом. Під аспидом можна розуміти наклеп, який, як аспид, вивергає отруту у вуха людей на обмовленого. Василіск — це заздрість: як василіск має шкоду в очах, так і заздрість одними очима шкодить тим, кому заздрять. Лев — це жорстокість і нелюдяність. Дракон — це лють через її полум’яність, гостроту й дію. Усі такі пристрасті праведник переможе й ніскільки не зазнає від них шкоди. І демон також є аспидом, василіском, левом і драконом, бо всі шкідливі дії, які чинять ці звірі, має в собі й він.","Прим.: І за словами великого Афанасія, Кирила й Діодора, під левом, драконом, аспидом і василіском можна розуміти самого сатану й лихих ангелів, що відступили з ним від Бога, які, не зберігши своєї влади, зазвичай виконують його волю. Якщо хочеш, під зміями й василісками можеш розуміти винахідників нечестивих єресей. За словами Євсевія: супротивні сили поділяються на чотири види — начальства, влади, світоправителі й духи злоби, що зображаються чотирма тваринами: левом, драконом, аспидом і василіском. Великий Василій каже, що василіск — це страшне породження змія, що вбиває, як кажуть, самим поглядом. Бо є переказ, що одним поглядом він губить тих, на кого гляне, кидаючи очима якусь згубну отруту. Слова Ниського: хто топче лють, той топче лева — цю люту тварину; а хто топче насолоди й іншу ваду, той топче аспида, василіска й дракона, бо тілесна насолода й усяке життєве зло доречно уподібнюється плазунам, що повзають по землі. Ще, можливо, власне василіска топче той, хто топче заздрість, як пануюче з лих. Бо тварина василіск носить шкоду в очах, як і заздрісні, кажуть, мають шкоду в очах."],"h":"На аспида й василіска наступиш, і потопчеш лева й дракона"},{"v":"14","t":["Пророк дав людині, що має своїм прибіжищем Бога, великі й неймовірні обітниці: що вона топтатиме найлютіших і найотруйніших звірів. Тому тепер, за словами Афанасія, він зображає Бога, Який запевняє в сказаному й навчає, яка нагорода й плід надії на Бога. Він каже: оскільки ця людина надіялася на Мене, то Я визволю її від усякої небезпеки.","«Покрию його, бо він пізнав ім’я Моє»","Зауваж, читачу, чому Бог сказав «бо він пізнав ім’я Моє»: тому, що Божого єства ніхто не може пізнати. А ім’я Боже пізнає не той, хто знає загалом, хто такий Бог, а той, хто поводиться щодо Бога гідно Бога. Тобто так, як належить поводитися щодо такого великого й страшного Бога, інакше кажучи, як раб, покірний божественним заповідям свого Владики.","Прим.: Євсевій питає: хто ж знає ім’я Його? І відповідає: той, хто Йому одному служить і Йому одному поклоняється, не знаючи іншого бога, окрім Нього; той, хто з лагідністю підкорив Йому волю свого розуму; хто служить Його волевиявленням, той знає Його волю. А коли чуєш «ім’я», розумій під ним славу. Так і написано, що краще добре ім’я, ніж велике багатство (Прит. 22:1)."],"h":"Бо на Мене він надіявся, і Я визволю його"},{"v":"15","t":["Той, хто надіється на Мене, каже, покличе, і Я почую його, бо він не проситиме нічого негідного Мого Божества, тобто Мене. У всякій спокусі й скорботі Я буду йому помічником, як був колись у печі з трьома отроками, а згодом — у стражданні з мучениками. І від усякої нужди звільню його, як ми сказали й у 36-му псалмі, пояснюючи слова «не бачив я праведника покинутим», а також «і Господь не залишить його в руках його». І не тільки звільню його, а й зроблю його славним і знаменитим через близькість, яку йому виявлю.","Прим.: Слова Афанасія: хто покличе Мене сильним голосом душі, той знайде Мене слухняним і готовим допомогти йому, бо Я завжди з ним, хоч би він і був у біді. Діодор: що може дати більше блаженства, ніж мати Бога, швидкого на допомогу й готового до бою з ворогами? Бо саме тоді найбільше потрібно, щоб Він був із нами, коли нас оточують скорботи й біди. Не тільки, каже, Я визволю його від скорбот, а й зроблю відомим усім. Тому скорбота вже не буде скорботою, а радістю й славою, бо Бог єднається й спілкується з тим, хто в скрутних обставинах."],"h":"Покличе Мене, і Я почую його; з ним Я в скорботі, вирву його і прославлю його"},{"v":"16","t":["Якщо, каже, той, хто надіється на Мене, проситиме й довгого життя, Я дам його йому. Або довготою днів називає вічне життя; бо те вічне життя, що зветься довготою днів, — один день через свою безконечність і безперервність.","Прим.: Феодорит і деякі інші кажуть, що сказане в цьому псалмі власне стосується царя Єзекії, а особливо останні слова пасують до тієї обставини, коли він отримав продовження життя й здобув велику славу від ассирійського царства. Феодорит додає й таке: і всі, хто надіється на Бога, отримають різноманітні блага, як це бачимо й з давніх розповідей і як про це свідчить і те, що бачимо нині (наступне написано в іншій книзі творів Феодорита): бо душі вибраних — у руці Господній. Їхні тіла, що лежать у гробницях, божественними знаменнями, що від них нині бувають, відкривають славне спасіння. Покладені за повелінням Владики в землю, вони точать зцілення, стали після Спасителя іншими спасителями й лікарями всякого роду хвороб. А їхні преблаженні останки після переможного знамення хреста стали знаменнями перемоги над демонами."],"h":"Довгими днями наситу його і явлю йому спасіння Моє"}]};
